import { useState, useMemo } from "react";

export default function PieChart({ data, title, colors = [] }) {
  const defaultColors = ["#4a7ba7", "#c5c5c5", "#fbbf24"];
  const chartColors = colors.length > 0 ? colors : defaultColors;

  const total = useMemo(() => data.reduce((sum, item) => sum + item.value, 0), [data]);

  const slices = useMemo(() => {
    let currentAngle = -90;
    return data.map((item, index) => {
      const sliceAngle = (item.value / total) * 360;
      const startAngle = currentAngle;
      const endAngle = currentAngle + sliceAngle;
      currentAngle = endAngle;

      const startRad = (startAngle * Math.PI) / 180;
      const endRad = (endAngle * Math.PI) / 180;
      const x1 = 50 + 40 * Math.cos(startRad);
      const y1 = 50 + 40 * Math.sin(startRad);
      const x2 = 50 + 40 * Math.cos(endRad);
      const y2 = 50 + 40 * Math.sin(endRad);

      const largeArc = sliceAngle > 180 ? 1 : 0;

      const pathData = [
        `M 50 50`,
        `L ${x1} ${y1}`,
        `A 40 40 0 ${largeArc} 1 ${x2} ${y2}`,
        "Z",
      ].join(" ");

      return {
        path: pathData,
        color: chartColors[index % chartColors.length],
        label: item.label,
        value: item.value,
        percentage: ((item.value / total) * 100).toFixed(1),
      };
    });
  }, [data, total, chartColors]);

  return (
    <div className="pie-chart-container">
      {title && <h3 className="chart-title">{title}</h3>}
      <div className="pie-chart-wrapper">
        <svg viewBox="0 0 100 100" className="pie-chart-svg">
          {slices.map((slice, index) => (
            <path key={index} d={slice.path} fill={slice.color} />
          ))}
        </svg>
        <div className="pie-chart-legend">
          {slices.map((slice, index) => (
            <div key={index} className="legend-item">
              <div
                className="legend-color"
                style={{ backgroundColor: slice.color }}
              />
              <div className="legend-text">
                <span className="legend-label">{slice.label}</span>
                <span className="legend-value">{slice.percentage}%</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useNotifications } from "../../hooks/useFirestoreData";
import { Bell, X, AlertCircle } from "lucide-react";
import { useState } from "react";

export default function NotificationsWidget() {
  const { data: notifications, loading, error } = useNotifications();
  const [expandedId, setExpandedId] = useState(null);

  const getNotificationIcon = (type) => {
    switch (type) {
      case "alert":
        return <AlertCircle size={16} />;
      case "booking":
        return <Bell size={16} />;
      default:
        return <Bell size={16} />;
    }
  };

  const getNotificationColor = (type) => {
    switch (type) {
      case "alert":
        return "notification-alert";
      case "booking":
        return "notification-booking";
      default:
        return "notification-default";
    }
  };

  if (loading) {
    return (
      <div className="notifications-widget glass">
        <div className="notifications-header">
          <h3>
            <Bell size={18} />
            Notifications
          </h3>
        </div>
        <div className="notifications-loading">Loading notifications...</div>
      </div>
    );
  }

  return (
    <div className="notifications-widget glass">
      <div className="notifications-header">
        <h3>
          <Bell size={18} />
          Notifications
          {notifications.length > 0 && (
            <span className="notification-count">{notifications.length}</span>
          )}
        </h3>
      </div>

      <div className="notifications-list">
        {notifications.length === 0 ? (
          <div className="no-notifications">
            <Bell size={32} />
            <p>No notifications yet</p>
          </div>
        ) : (
          notifications.slice(0, 5).map((notif) => (
            <div
              key={notif.id}
              className={`notification-item ${getNotificationColor(notif.type)}`}
            >
              <div className="notification-icon">
                {getNotificationIcon(notif.type)}
              </div>
              <div className="notification-content">
                <p className="notification-title">{notif.title}</p>
                <p className="notification-message">{notif.message}</p>
                <span className="notification-time">
                  {notif.createdAt
                    ? new Date(notif.createdAt.seconds * 1000).toLocaleTimeString(
                        [],
                        { hour: "2-digit", minute: "2-digit" }
                      )
                    : "Just now"}
                </span>
              </div>
              <button
                className="notification-close"
                onClick={() => setExpandedId(null)}
              >
                <X size={14} />
              </button>
            </div>
          ))
        )}
      </div>

      {notifications.length > 5 && (
        <div className="notifications-footer">
          <a href="/notifications" className="view-all-link">
            View all notifications
          </a>
        </div>
      )}
    </div>
  );
}

import { useWeeklyAnalysis } from "../../hooks/useFirestoreData";
import { TrendingUp, Calendar } from "lucide-react";

export default function WeeklyAnalysis() {
  const { data: weeklyData, loading, error } = useWeeklyAnalysis();

  if (loading) {
    return (
      <div className="weekly-analysis-card glass">
        <div className="analysis-header">
          <div className="analysis-title">
            <Calendar size={20} />
            <h3>7-Day Analysis</h3>
          </div>
          <TrendingUp size={20} className="trending-icon" />
        </div>
        <div className="analysis-loading">Loading analytics...</div>
      </div>
    );
  }

  const hasData = weeklyData.some((day) => day.events > 0 || day.revenue > 0);
  const totalEvents = weeklyData.reduce((sum, day) => sum + day.events, 0);
  const totalRevenue = weeklyData.reduce((sum, day) => sum + day.revenue, 0);
  const avgDaily = weeklyData.length
    ? (totalEvents / weeklyData.length).toFixed(1)
    : "0";

  const maxEvents = Math.max(...weeklyData.map((d) => d.events), 1);

  const renderEmptyState = () => (
    <div className="analysis-empty">
      <p>No weekly activity found yet.</p>
      <span>Events will appear here once your dashboard receives data.</span>
    </div>
  );

  return (
    <div className="weekly-analysis-card glass">
      <div className="analysis-header">
        <div className="analysis-title">
          <Calendar size={20} />
          <h3>7-Day Analysis</h3>
        </div>
        <TrendingUp size={20} className="trending-icon" />
      </div>

      {!hasData && !loading ? (
        renderEmptyState()
      ) : (
        <>
          <div className="analysis-stats">
            <div className="stat-item">
              <span className="stat-label">Total Events</span>
              <span className="stat-value">{totalEvents}</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Avg Daily</span>
              <span className="stat-value">{avgDaily}</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Total Revenue</span>
              <span className="stat-value">₦{totalRevenue.toLocaleString()}</span>
            </div>
          </div>

          <div className="analysis-chart">
            <div className="chart-bars">
              {weeklyData.map((day, index) => (
                <div key={index} className="chart-bar-container">
                  <div
                    className="chart-bar"
                    style={{
                      height:
                        maxEvents > 0
                          ? `${(day.events / maxEvents) * 100}%`
                          : "8%",
                    }}
                    title={`${day.day}: ${day.events} events`}
                  />
                  <span className="bar-label">{day.day}</span>
                </div>
              ))}
            </div>
          </div>

          <div className="analysis-footer">
            <p className="analysis-text">
              {totalEvents === 0
                ? "No events recorded this week. Start planning!"
                : `You've had ${totalEvents} events this week. Keep going!`}
            </p>
          </div>
        </>
      )}
    </div>
  );
}

