import {
  createContext,
  useContext,
  useEffect,
  useState,
} from "react";

import {
  onAuthStateChanged,
} from "firebase/auth";

import {
  doc,
  getDoc,
} from "firebase/firestore";

import {
  auth,
  db,
} from "../firebase/firebase";

const AuthContext = createContext();

export function AuthProvider({ children }) {

  const [user, setUser] = useState(null);

  const [loading, setLoading] = useState(true);

  const [profile, setProfile] = useState(null);

  const [role, setRole] = useState(null);

  const refreshProfile = async (uid) => {

    if (!uid) {
      setProfile(null);
      setRole(null);
      return null;
    }

    const docRef =
      doc(db, "users", uid);

    const docSnap =
      await getDoc(docRef);

    if (!docSnap.exists()) {
      setProfile(null);
      setRole(null);
      return null;
    }

    const profileData =
      docSnap.data();

    setProfile(profileData);
    setRole(profileData.role ?? null);

    return profileData;
  };

  useEffect(() => {

    const unsubscribe =
      onAuthStateChanged(auth, async (currentUser) => {

        try {

          if (currentUser) {

            setUser(currentUser);
            await refreshProfile(currentUser.uid);

          } else {

            setUser(null);
            setProfile(null);
            setRole(null);
          }

        } catch (error) {

          console.error("Auth context failed to load profile:", error);
          setUser(currentUser ?? null);
          setProfile(null);
          setRole(null);

        } finally {

          setLoading(false);
        }
      });

    return unsubscribe;

  }, []);

  return (
    <AuthContext.Provider
      value={{
        refreshProfile,
        profile,
        user,
        role,
        onboardingCompleted:
          Boolean(profile?.onboardingCompleted),
      }}
    >
      {!loading && children}
    </AuthContext.Provider>
  );
}

export function useAuth() {

  return useContext(AuthContext);
}

import { useState, useEffect } from "react";
import {
  collection,
  query,
  where,
  onSnapshot,
  getDocs,
  collectionGroup,
} from "firebase/firestore";
import { db, auth } from "../firebase/firebase";

export function useRealTimeStats() {
  const [stats, setStats] = useState({
    totalEvents: 0,
    bookings: 0,
    revenue: 0,
    loading: true,
    error: null,
  });

  useEffect(() => {
    if (!auth.currentUser) {
      setStats((prev) => ({ ...prev, loading: false }));
      return;
    }

    try {
      // Subscribe to events collection
      const eventsRef = collection(db, "events");
      const q = query(eventsRef, where("userId", "==", auth.currentUser.uid));

      const unsubscribe = onSnapshot(
        q,
        (snapshot) => {
          let totalEvents = snapshot.docs.length;
          let bookings = 0;
          let revenue = 0;

          snapshot.docs.forEach((doc) => {
            const data = doc.data();
            bookings += data.bookings || 0;
            revenue += data.revenue || 0;
          });

          setStats({
            totalEvents,
            bookings,
            revenue,
            loading: false,
            error: null,
          });
        },
        (error) => {
          console.error("Error fetching stats:", error);
          setStats((prev) => ({
            ...prev,
            loading: false,
            error: error.message,
          }));
        }
      );

      return unsubscribe;
    } catch (error) {
      console.error("Error setting up stats listener:", error);
      setStats((prev) => ({
        ...prev,
        loading: false,
        error: error.message,
      }));
    }
  }, []);

  return stats;
}

export function useNotifications() {
  const [notifications, setNotifications] = useState({
    data: [],
    loading: true,
    error: null,
  });

  useEffect(() => {
    if (!auth.currentUser) {
      setNotifications((prev) => ({ ...prev, loading: false }));
      return;
    }

    try {
      const notificationsRef = collection(
        db,
        "users",
        auth.currentUser.uid,
        "notifications"
      );
      const q = query(
        notificationsRef
      );

      const unsubscribe = onSnapshot(
        q,
        (snapshot) => {
          const notifs = snapshot.docs.map((doc) => ({
            id: doc.id,
            ...doc.data(),
          }));

          setNotifications({
            data: notifs,
            loading: false,
            error: null,
          });
        },
        (error) => {
          console.error("Error fetching notifications:", error);
          setNotifications((prev) => ({
            ...prev,
            loading: false,
            error: error.message,
          }));
        }
      );

      return unsubscribe;
    } catch (error) {
      console.error("Error setting up notifications listener:", error);
      setNotifications((prev) => ({
        ...prev,
        loading: false,
        error: error.message,
      }));
    }
  }, []);

  return notifications;
}

export function useWeeklyAnalysis() {
  const [analysis, setAnalysis] = useState({
    data: [],
    loading: true,
    error: null,
  });

  useEffect(() => {
    if (!auth.currentUser) {
      setAnalysis((prev) => ({ ...prev, loading: false }));
      return;
    }

    try {
      const analysisRef = collection(
        db,
        "users",
        auth.currentUser.uid,
        "weeklyAnalysis"
      );

      const unsubscribe = onSnapshot(
        analysisRef,
        (snapshot) => {
          // Get last 7 days of data
          const today = new Date();
          const last7Days = [];

          for (let i = 6; i >= 0; i--) {
            const date = new Date(today);
            date.setDate(date.getDate() - i);
            last7Days.push({
              date: date.toISOString().split("T")[0],
              day: date.toLocaleDateString("en-US", { weekday: "short" }),
              events: 0,
              revenue: 0,
            });
          }

          snapshot.docs.forEach((doc) => {
            const data = doc.data();
            const dayData = last7Days.find((d) => d.date === data.date);
            if (dayData) {
              dayData.events = data.events || 0;
              dayData.revenue = data.revenue || 0;
            }
          });

          setAnalysis({
            data: last7Days,
            loading: false,
            error: null,
          });
        },
        (error) => {
          console.error("Error fetching weekly analysis:", error);
          setAnalysis((prev) => ({
            ...prev,
            loading: false,
            error: error.message,
          }));
        }
      );

      return unsubscribe;
    } catch (error) {
      console.error("Error setting up analysis listener:", error);
      setAnalysis((prev) => ({
        ...prev,
        loading: false,
        error: error.message,
      }));
    }
  }, []);

  return analysis;
}

import { useState, useEffect } from "react";
import {
  collection,
  query,
  orderBy,
  onSnapshot,
  updateDoc,
  doc,
  serverTimestamp,
  deleteDoc,
  where,
  getDocs,
  count,
} from "firebase/firestore";
import { Shield, Users, CheckCircle, XCircle, Eye, Trash2, BarChart3, Settings, FileText, Search, TrendingUp, AlertTriangle } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

export default function AdminPanel() {
  const [activeTab, setActiveTab] = useState("overview");
  const [users, setUsers] = useState([]);
  const [pendingVendors, setPendingVendors] = useState([]);
  const [allEvents, setAllEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");

  useEffect(() => {
    const unsubUsers = onSnapshot(query(collection(db, "users"), orderBy("createdAt", "desc")), (snap) => {
      setUsers(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
      setLoading(false);
    });

    const unsubVendors = onSnapshot(
      query(collection(db, "vendors"), where("verified", "==", false)),
      (snap) => setPendingVendors(snap.docs.map((d) => ({ id: d.id, ...d.data() })))
    );

    const unsubEvents = onSnapshot(query(collection(db, "events"), orderBy("createdAt", "desc")), (snap) => {
      setAllEvents(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    });

    return () => { unsubUsers(); unsubVendors(); unsubEvents(); };
  }, []);

  const handleApproveVendor = async (vendorId) => {
    await updateDoc(doc(db, "vendors", vendorId), {
      verified: true,
      verifiedAt: serverTimestamp(),
      verifiedBy: auth.currentUser.uid,
    });
  };

  const handleRejectVendor = async (vendorId) => {
    if (!window.confirm("Reject this vendor?")) return;
    await deleteDoc(doc(db, "vendors", vendorId));
  };

  const handleBanUser = async (userId) => {
    if (!window.confirm("Ban this user?")) return;
    await updateDoc(doc(db, "users", userId), {
      banned: true,
      bannedAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
    });
  };

  const stats = {
    totalUsers: users.length,
    totalVendors: users.filter((u) => u.role === "vendor").length,
    totalPlanners: users.filter((u) => u.role === "planner").length,
    totalEvents: allEvents.length,
    pendingApprovals: pendingVendors.length,
    bannedUsers: users.filter((u) => u.banned).length,
  };

  const filteredUsers = users.filter((u) => {
    const q = search.toLowerCase();
    return u.fullName?.toLowerCase().includes(q) || u.email?.toLowerCase().includes(q) || u.role?.toLowerCase().includes(q);
  });

  const tabs = [
    { id: "overview", label: "Overview", icon: <BarChart3 size={16} /> },
    { id: "users", label: "Users", icon: <Users size={16} /> },
    { id: "vendors", label: "Vendor Approvals", icon: <CheckCircle size={16} /> },
    { id: "events", label: "Events", icon: <FileText size={16} /> },
    { id: "settings", label: "Settings", icon: <Settings size={16} /> },
  ];

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">Admin Portal</div>
            <h1>Admin Panel</h1>
            <p>Manage users, vendors, events, and platform settings.</p>
          </div>
        </div>

        {/* Tabs */}
        <div style={{ display: "flex", gap: "8px", marginBottom: "1.5rem", flexWrap: "wrap" }}>
          {tabs.map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id)} style={{ padding: "8px 16px", borderRadius: "8px", border: activeTab === tab.id ? "2px solid #fbbf24" : "1px solid rgba(0,0,0,0.15)", background: activeTab === tab.id ? "rgba(251,191,36,0.15)" : "rgba(0,0,0,0.05)", color: "#000", cursor: "pointer", fontSize: "0.85rem", display: "flex", alignItems: "center", gap: "6px" }}>
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>

        {/* Overview */}
        {activeTab === "overview" && (
          <>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: "12px", marginBottom: "1.5rem" }}>
              {[
                { label: "Total Users", value: stats.totalUsers, color: "#fbbf24" },
                { label: "Vendors", value: stats.totalVendors, color: "#3b82f6" },
                { label: "Planners", value: stats.totalPlanners, color: "#8b5cf6" },
                { label: "Total Events", value: stats.totalEvents, color: "#22c55e" },
                { label: "Pending Approvals", value: stats.pendingApprovals, color: "#f97316" },
                { label: "Banned Users", value: stats.bannedUsers, color: "#ef4444" },
              ].map((s, i) => (
                <div key={i} className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
                  <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.75rem" }}>{s.label}</p>
                  <h3 style={{ color: s.color, fontSize: "1.5rem" }}>{s.value}</h3>
                </div>
              ))}
            </div>

            {/* Recent Users */}
            <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
              <h3 style={{ color: "#fbbf24", marginBottom: "12px" }}>Recent Users</h3>
              {users.slice(0, 5).map((u) => (
                <div key={u.id} style={{ display: "flex", alignItems: "center", gap: "10px", padding: "8px 0", borderBottom: "1px solid rgba(0,0,0,0.05)" }}>
                  <div style={{ width: "32px", height: "32px", borderRadius: "50%", background: "linear-gradient(135deg, #fbbf24, #d97706)", display: "flex", alignItems: "center", justifyContent: "center", color: "#000", fontWeight: 700, fontSize: "0.75rem" }}>
                    {u.fullName?.charAt(0)?.toUpperCase() || "?"}
                  </div>
                  <div style={{ flex: 1 }}>
                    <p style={{ color: "#000", fontSize: "0.85rem" }}>{u.fullName}</p>
                    <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.75rem" }}>{u.email}</p>
                  </div>
                  <span style={{ padding: "2px 8px", borderRadius: "10px", background: "rgba(251,191,36,0.1)", color: "#fbbf24", fontSize: "0.7rem", textTransform: "capitalize" }}>{u.role || "user"}</span>
                </div>
              ))}
            </div>
          </>
        )}

        {/* Users Tab */}
        {activeTab === "users" && (
          <>
            <div style={{ position: "relative", marginBottom: "1rem" }}>
              <Search size={16} style={{ position: "absolute", left: "12px", top: "50%", transform: "translateY(-50%)", color: "rgba(0,0,0,0.3)" }} />
              <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search users..." className="auth-input" style={{ paddingLeft: "36px" }} />
            </div>
            <div className="glass" style={{ borderRadius: "12px", overflow: "hidden" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", color: "#000" }}>
                <thead>
                  <tr style={{ borderBottom: "1px solid rgba(0,0,0,0.1)" }}>
                    <th style={{ padding: "12px", textAlign: "left", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>User</th>
                    <th style={{ padding: "12px", textAlign: "left", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>Role</th>
                    <th style={{ padding: "12px", textAlign: "left", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>Status</th>
                    <th style={{ padding: "12px", textAlign: "left", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>Joined</th>
                    <th style={{ padding: "12px", textAlign: "right", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredUsers.map((u) => (
                    <tr key={u.id} style={{ borderBottom: "1px solid rgba(0,0,0,0.05)" }}>
                      <td style={{ padding: "12px" }}>
                        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                          <div style={{ width: "28px", height: "28px", borderRadius: "50%", background: "linear-gradient(135deg, #fbbf24, #d97706)", display: "flex", alignItems: "center", justifyContent: "center", color: "#000", fontWeight: 700, fontSize: "0.7rem" }}>
                            {u.fullName?.charAt(0)?.toUpperCase()}
                          </div>
                          <div>
                            <p style={{ fontSize: "0.85rem" }}>{u.fullName}</p>
                            <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.7rem" }}>{u.email}</p>
                          </div>
                        </div>
                      </td>
                      <td style={{ padding: "12px" }}>
                        <span style={{ padding: "2px 8px", borderRadius: "10px", background: "rgba(251,191,36,0.1)", color: "#fbbf24", fontSize: "0.7rem", textTransform: "capitalize" }}>{u.role || "user"}</span>
                      </td>
                      <td style={{ padding: "12px" }}>
                        <span style={{ padding: "2px 8px", borderRadius: "10px", background: u.banned ? "rgba(239,68,68,0.1)" : "rgba(34,197,94,0.1)", color: u.banned ? "#ef4444" : "#22c55e", fontSize: "0.7rem" }}>
                          {u.banned ? "Banned" : "Active"}
                        </span>
                      </td>
                      <td style={{ padding: "12px", color: "rgba(0,0,0,0.4)", fontSize: "0.8rem" }}>
                        {u.createdAt?.toDate?.().toLocaleDateString() || "—"}
                      </td>
                      <td style={{ padding: "12px", textAlign: "right" }}>
                        {!u.banned && (
                          <button onClick={() => handleBanUser(u.id)} style={{ padding: "4px 8px", borderRadius: "4px", background: "rgba(239,68,68,0.15)", border: "none", color: "#ef4444", cursor: "pointer", fontSize: "0.75rem" }}>Ban</button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}

        {/* Vendor Approvals */}
        {activeTab === "vendors" && (
          <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
            <h3 style={{ color: "#fbbf24", marginBottom: "12px" }}>Pending Vendor Approvals ({pendingVendors.length})</h3>
            {pendingVendors.length === 0 ? (
              <p style={{ color: "rgba(0,0,0,0.3)", textAlign: "center", padding: "2rem" }}>No pending approvals</p>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
                {pendingVendors.map((v) => (
                  <div key={v.id} style={{ display: "flex", alignItems: "center", gap: "12px", padding: "12px", borderRadius: "8px", background: "rgba(0,0,0,0.03)" }}>
                    <div style={{ width: "40px", height: "40px", borderRadius: "8px", background: "linear-gradient(135deg, #fbbf24, #d97706)", display: "flex", alignItems: "center", justifyContent: "center", color: "#000", fontWeight: 700 }}>
                      {v.businessName?.charAt(0)?.toUpperCase() || "V"}
                    </div>
                    <div style={{ flex: 1 }}>
                      <p style={{ color: "#000", fontSize: "0.9rem" }}>{v.businessName || "Unnamed Vendor"}</p>
                      <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.75rem" }}>{v.category || "General"} • {v.email || "No email"}</p>
                    </div>
                    <button onClick={() => handleApproveVendor(v.id)} style={{ padding: "6px 14px", borderRadius: "6px", background: "rgba(34,197,94,0.15)", border: "none", color: "#22c55e", cursor: "pointer", fontSize: "0.8rem", display: "flex", alignItems: "center", gap: "4px" }}>
                      <CheckCircle size={14} /> Approve
                    </button>
                    <button onClick={() => handleRejectVendor(v.id)} style={{ padding: "6px 14px", borderRadius: "6px", background: "rgba(239,68,68,0.15)", border: "none", color: "#ef4444", cursor: "pointer", fontSize: "0.8rem", display: "flex", alignItems: "center", gap: "4px" }}>
                      <XCircle size={14} /> Reject
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Events Tab */}
        {activeTab === "events" && (
          <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
            <h3 style={{ color: "#fbbf24", marginBottom: "12px" }}>All Events ({allEvents.length})</h3>
            {allEvents.map((ev) => (
              <div key={ev.id} style={{ display: "flex", alignItems: "center", gap: "12px", padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.03)", marginBottom: "6px" }}>
                <div style={{ flex: 1 }}>
                  <p style={{ color: "#000", fontSize: "0.9rem" }}>{ev.title}</p>
                  <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.75rem" }}>{ev.date || "No date"} • {ev.eventType || "Other"}</p>
                </div>
                <span style={{ padding: "2px 8px", borderRadius: "10px", background: ev.status === "completed" ? "rgba(34,197,94,0.1)" : "rgba(251,191,36,0.1)", color: ev.status === "completed" ? "#22c55e" : "#fbbf24", fontSize: "0.7rem", textTransform: "capitalize" }}>
                  {ev.status || "planning"}
                </span>
              </div>
            ))}
          </div>
        )}

        {/* Settings */}
        {activeTab === "settings" && (
          <div className="glass" style={{ padding: "20px", borderRadius: "12px" }}>
            <h3 style={{ color: "#fbbf24", marginBottom: "16px" }}>Platform Settings</h3>
            <div style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
              {[
                { label: "Enable OmaPay", desc: "Allow wallet and payment features", checked: true },
                { label: "Enable Oma AI", desc: "Enable AI assistant across platform", checked: true },
                { label: "Auto-verify Vendors", desc: "Automatically approve vendor registrations", checked: false },
                { label: "Maintenance Mode", desc: "Put platform in maintenance mode", checked: false },
              ].map((s, i) => (
                <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px", borderRadius: "8px", background: "rgba(0,0,0,0.03)" }}>
                  <div>
                    <p style={{ color: "#000", fontSize: "0.9rem" }}>{s.label}</p>
                    <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.75rem" }}>{s.desc}</p>
                  </div>
                  <label style={{ position: "relative", width: "44px", height: "24px" }}>
                    <input type="checkbox" defaultChecked={s.checked} style={{ display: "none" }} />
                    <div style={{ width: "100%", height: "100%", borderRadius: "12px", background: s.checked ? "#fbbf24" : "rgba(0,0,0,0.2)", cursor: "pointer", transition: "background 0.3s" }}>
                      <div style={{ width: "20px", height: "20px", borderRadius: "50%", background: "#000", position: "absolute", top: "2px", left: s.checked ? "22px" : "2px", transition: "left 0.3s" }} />
                    </div>
                  </label>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect } from "react";
import { collection, query, where, onSnapshot, orderBy } from "firebase/firestore";
import { BarChart3, TrendingUp, TrendingDown, DollarSign, Users, Calendar, Download } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";
import PieChart from "../../components/charts/PieChart";
import BarChart from "../../components/charts/BarChart";
import LineChart from "../../components/charts/LineChart";

export default function Analytics() {
  const [events, setEvents] = useState([]);
  const [expenses, setExpenses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [period, setPeriod] = useState("all");

  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;

    const eventsUnsub = onSnapshot(
      query(collection(db, "events"), where("userId", "==", uid), orderBy("createdAt", "desc")),
      (snap) => { setEvents(snap.docs.map((d) => ({ id: d.id, ...d.data() }))); setLoading(false); }
    );

    const expensesUnsub = onSnapshot(
      query(collection(db, "expenses"), where("userId", "==", uid)),
      (snap) => setExpenses(snap.docs.map((d) => ({ id: d.id, ...d.data() })))
    );

    return () => { eventsUnsub(); expensesUnsub(); };
  }, []);

  const totalEvents = events.length;
  const completedEvents = events.filter((e) => e.status === "completed").length;
  const totalBudget = events.reduce((s, e) => s + (Number(e.budget) || 0), 0);
  const totalSpent = expenses.reduce((s, e) => s + (Number(e.amount) || 0), 0);
  const avgBudget = totalEvents > 0 ? totalBudget / totalEvents : 0;
  const budgetVariance = totalBudget - totalSpent;

  const eventTypeData = {};
  events.forEach((e) => {
    const type = e.eventType || "other";
    eventTypeData[type] = (eventTypeData[type] || 0) + 1;
  });
  const pieData = Object.entries(eventTypeData).map(([label, value]) => ({ label: label.charAt(0).toUpperCase() + label.slice(1), value }));

  const categoryTotals = {};
  expenses.forEach((e) => {
    const cat = e.category || "Other";
    categoryTotals[cat] = (categoryTotals[cat] || 0) + (Number(e.amount) || 0);
  });
  const barData = Object.entries(categoryTotals)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 6)
    .map(([label, value]) => ({ label, value }));

  const monthlyData = [];
  const now = new Date();
  for (let i = 5; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const monthStr = d.toLocaleString("default", { month: "short" });
    const monthEvents = events.filter((e) => {
      const ed = e.date ? new Date(e.date) : null;
      return ed && ed.getMonth() === d.getMonth() && ed.getFullYear() === d.getFullYear();
    }).length;
    const monthExpenses = expenses.filter((e) => {
      const ed = e.createdAt?.toDate?.() || new Date();
      return ed.getMonth() === d.getMonth() && ed.getFullYear() === d.getFullYear();
    }).reduce((s, e) => s + (Number(e.amount) || 0), 0);
    monthlyData.push({ label: monthStr, value1: monthEvents, value2: monthExpenses / 1000 });
  }

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">Analytics</div>
            <h1>Analytics Dashboard</h1>
            <p>Comprehensive insights into your event business performance.</p>
          </div>
          <button style={{ padding: "8px 16px", borderRadius: "8px", background: "rgba(251,191,36,0.15)", border: "1px solid rgba(251,191,36,0.3)", color: "#fbbf24", cursor: "pointer", fontSize: "0.85rem", display: "flex", alignItems: "center", gap: "6px" }}>
            <Download size={16} /> Export Report
          </button>
        </div>

        {/* Period Filter */}
        <div style={{ display: "flex", gap: "8px", marginBottom: "1.5rem" }}>
          {["week", "month", "quarter", "all"].map((p) => (
            <button key={p} onClick={() => setPeriod(p)} style={{ padding: "6px 14px", borderRadius: "8px", border: period === p ? "2px solid #fbbf24" : "1px solid rgba(0,0,0,0.15)", background: period === p ? "rgba(251,191,36,0.15)" : "rgba(0,0,0,0.05)", color: "#000", cursor: "pointer", fontSize: "0.8rem", textTransform: "capitalize" }}>
              {p === "all" ? "All Time" : p}
            </button>
          ))}
        </div>

        {/* KPI Cards */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: "12px", marginBottom: "1.5rem" }}>
          {[
            { label: "Total Events", value: totalEvents, icon: <Calendar size={20} />, color: "#fbbf24", change: "+12%" },
            { label: "Completed", value: completedEvents, icon: <BarChart3 size={20} />, color: "#22c55e", change: "+8%" },
            { label: "Total Budget", value: `₦${totalBudget.toLocaleString()}`, icon: <DollarSign size={20} />, color: "#3b82f6", change: "+15%" },
            { label: "Total Spent", value: `₦${totalSpent.toLocaleString()}`, icon: <TrendingUp size={20} />, color: "#f97316", change: "+10%" },
            { label: "Budget Variance", value: `₦${budgetVariance.toLocaleString()}`, icon: budgetVariance >= 0 ? <TrendingUp size={20} /> : <TrendingDown size={20} />, color: budgetVariance >= 0 ? "#22c55e" : "#ef4444" },
            { label: "Avg Budget/Event", value: `₦${Math.round(avgBudget).toLocaleString()}`, icon: <DollarSign size={20} />, color: "#8b5cf6" },
          ].map((kpi, i) => (
            <div key={i} className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "8px" }}>
                <span style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.75rem" }}>{kpi.label}</span>
                <span style={{ color: kpi.color }}>{kpi.icon}</span>
              </div>
              <h3 style={{ color: "#000", fontSize: "1.3rem" }}>{kpi.value}</h3>
              {kpi.change && <p style={{ color: "#22c55e", fontSize: "0.7rem", marginTop: "4px" }}>{kpi.change} from last period</p>}
            </div>
          ))}
        </div>

        {/* Charts */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "16px", marginBottom: "1.5rem" }}>
          <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
            <PieChart data={pieData.length > 0 ? pieData : [{ label: "No Data", value: 1 }]} title="Event Types" colors={["#fbbf24", "#d97706", "#3b82f6", "#22c55e", "#ef4444", "#8b5cf6"]} />
          </div>
          <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
            <BarChart data={barData.length > 0 ? barData : [{ label: "No Data", value: 1 }]} title="Spending by Category" colors={["#fbbf24"]} />
          </div>
        </div>

        <div className="glass" style={{ padding: "16px", borderRadius: "12px", marginBottom: "1.5rem" }}>
          <LineChart data={monthlyData} title="Events & Spending Trend" lines={[{ key: "value1", stroke: "#fbbf24", label: "Events" }, { key: "value2", stroke: "#3b82f6", label: "Spending (K)" }]} />
        </div>

        {/* Vendor Performance */}
        <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
          <h3 style={{ color: "#fbbf24", marginBottom: "12px" }}>Event Status Breakdown</h3>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: "12px" }}>
            {["planning", "in-progress", "completed", "cancelled"].map((status) => {
              const count = events.filter((e) => e.status === status).length;
              const colors = { planning: "#fbbf24", "in-progress": "#3b82f6", completed: "#22c55e", cancelled: "#ef4444" };
              return (
                <div key={status} style={{ textAlign: "center", padding: "16px", borderRadius: "10px", background: `${colors[status]}11` }}>
                  <h3 style={{ color: colors[status], fontSize: "1.5rem" }}>{count}</h3>
                  <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.8rem", textTransform: "capitalize" }}>{status.replace("-", " ")}</p>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
}

import { useEffect, useState } from "react";
import {
  doc,
  serverTimestamp,
  setDoc,
} from "firebase/firestore";
import { useNavigate } from "react-router-dom";

import ProgressSteps from "../../components/auth/ProgressSteps";
import RoleSelector from "../../components/auth/RoleSelector";
import AuthLayout from "../../components/layout/AuthLayout";
import { useAuth } from "../../context/AuthContext";
import { db } from "../../firebase/firebase";

const steps = [
  "Account",
  "Profile",
  "Dashboard",
];

export default function Onboarding() {

  const navigate = useNavigate();

  const {
    profile,
    refreshProfile,
    user,
  } = useAuth();

  const [formData, setFormData] =
    useState({
      businessName: "",
      planningFocus: "",
      role: "",
    });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!profile) {
      return;
    }

    setFormData((currentData) => ({
      businessName:
        profile.businessName ?? currentData.businessName,
      planningFocus:
        profile.planningFocus ?? currentData.planningFocus,
      role:
        profile.role ?? currentData.role,
    }));
  }, [profile]);

  const handleChange = (event) => {
    const { name, value } = event.target;

    setFormData((currentData) => ({
      ...currentData,
      [name]: value,
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    setError("");

    if (!formData.role) {
      setError("Select how you want to use OMA");
      return;
    }

    if (!formData.planningFocus.trim()) {
      setError("Tell us what you want to manage");
      return;
    }

    try {
      setLoading(true);

      await setDoc(doc(db, "users", user.uid), {
        businessName: formData.businessName.trim(),
        onboardingCompleted: true,
        planningFocus: formData.planningFocus.trim(),
        role: formData.role,
        updatedAt: serverTimestamp(),
      }, { merge: true });

      await refreshProfile(user.uid);

      navigate("/dashboard");
    } catch (saveError) {
      console.error(saveError);
      setError("We could not finish your setup");
    } finally {
      setLoading(false);
    }
  };

  return (
    <AuthLayout>
      <form
        onSubmit={handleSubmit}
        className="auth-card auth-card-wide glass"
      >
        <div className="auth-step-copy">
          <p className="auth-kicker">
            Step 2 of 3
          </p>

          <h2 className="auth-card-title">
            Personalize your workspace
          </h2>

          <p className="auth-card-subtitle">
            Choose your role and describe the kind of events or services you want to manage.
          </p>
        </div>

        <ProgressSteps
          steps={steps}
          currentStep={2}
        />

        {error && <div className="auth-error">{error}</div>}

        <div className="auth-role-section">
          <RoleSelector
            selectedRole={formData.role}
            onSelect={(role) =>
              setFormData((currentData) => ({
                ...currentData,
                role,
              }))
            }
          />
        </div>

        <div className="auth-form-fields">
          <input
            type="text"
            name="businessName"
            placeholder="Business or team name (optional)"
            value={formData.businessName}
            onChange={handleChange}
            className="auth-input"
          />

          <textarea
            name="planningFocus"
            placeholder="What are you planning or selling on OMA?"
            value={formData.planningFocus}
            onChange={handleChange}
            className="auth-input auth-textarea"
            rows="4"
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="auth-submit"
        >
          {
            loading
              ? "Finishing setup..."
              : "Finish and open dashboard"
          }
        </button>
      </form>
    </AuthLayout>
  );
}

import { useState, useEffect } from "react";
import {
  collection,
  query,
  where,
  onSnapshot,
  addDoc,
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp,
} from "firebase/firestore";
import { DollarSign, Plus, Trash2, Edit3, TrendingUp, TrendingDown, AlertTriangle, Upload } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

const categories = [
  "Venue", "Catering", "Decoration", "Photography", "Videography",
  "Music & DJ", "MC/Host", "Transport", "Fashion", "Security",
  "Invitation", "Gifts", "Sound & Lighting", "Florist", "Other",
];

const categoryIcons = {
  Venue: "🏛️", Catering: "🍽️", Decoration: "🎨", Photography: "📸",
  Videography: "🎬", "Music & DJ": "🎵", "MC/Host": "🎤", Transport: "🚗",
  Fashion: "👗", Security: "🛡️", Invitation: "💌", Gifts: "🎁",
  "Sound & Lighting": "🔊", Florist: "💐", Other: "📦",
};

export default function BudgetManagement() {
  const [events, setEvents] = useState([]);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [expenses, setExpenses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [editingExpense, setEditingExpense] = useState(null);
  const [activeTab, setActiveTab] = useState("overview");
  const [form, setForm] = useState({
    title: "",
    amount: "",
    category: "Venue",
    vendor: "",
    status: "pending",
    notes: "",
    dueDate: "",
  });

  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;
    const q = query(collection(db, "events"), where("userId", "==", uid));
    const unsub = onSnapshot(q, (snap) => {
      const list = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      setEvents(list);
      setSelectedEvent((current) => current ?? list[0]?.id ?? null);
      setLoading(false);
    });
    return unsub;
  }, []);

  useEffect(() => {
    if (!selectedEvent) return;
    const q = query(collection(db, "expenses"), where("eventId", "==", selectedEvent));
    const unsub = onSnapshot(q, (snap) => {
      setExpenses(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    });
    return unsub;
  }, [selectedEvent]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.title || !form.amount || !selectedEvent) return;
    if (editingExpense) {
      await updateDoc(doc(db, "expenses", editingExpense.id), { ...form, amount: Number(form.amount), updatedAt: serverTimestamp() });
      setEditingExpense(null);
    } else {
      await addDoc(collection(db, "expenses"), {
        ...form,
        amount: Number(form.amount),
        eventId: selectedEvent,
        userId: auth.currentUser.uid,
        createdAt: serverTimestamp(),
      });
    }
    setForm({ title: "", amount: "", category: "Venue", vendor: "", status: "pending", notes: "", dueDate: "" });
    setShowAdd(false);
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Delete this expense?")) return;
    await deleteDoc(doc(db, "expenses", id));
  };

  const handleEdit = (expense) => {
    setEditingExpense(expense);
    setForm({
      title: expense.title,
      amount: expense.amount,
      category: expense.category,
      vendor: expense.vendor || "",
      status: expense.status,
      notes: expense.notes || "",
      dueDate: expense.dueDate || "",
    });
    setShowAdd(true);
  };

  const handleStatusChange = async (id, status) => {
    await updateDoc(doc(db, "expenses", id), { status, updatedAt: serverTimestamp() });
  };

  const currentEvent = events.find((e) => e.id === selectedEvent);
  const totalBudget = Number(currentEvent?.budget) || 0;
  const totalSpent = expenses.reduce((sum, e) => sum + (Number(e.amount) || 0), 0);
  const totalPending = expenses.filter((e) => e.status === "pending").reduce((sum, e) => sum + (Number(e.amount) || 0), 0);
  const totalPaid = expenses.filter((e) => e.status === "paid").reduce((sum, e) => sum + (Number(e.amount) || 0), 0);
  const remaining = totalBudget - totalSpent;
  const budgetPercent = totalBudget > 0 ? Math.min((totalSpent / totalBudget) * 100, 100) : 0;

  const categoryTotals = {};
  expenses.forEach((e) => {
    categoryTotals[e.category] = (categoryTotals[e.category] || 0) + (Number(e.amount) || 0);
  });

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">Budget & Finance</div>
            <h1>Budget Management</h1>
            <p>Track expenses, manage invoices, and stay within budget.</p>
          </div>
          {selectedEvent && (
            <button onClick={() => { setShowAdd(true); setEditingExpense(null); setForm({ title: "", amount: "", category: "Venue", vendor: "", status: "pending", notes: "", dueDate: "" }); }} className="auth-submit" style={{ display: "inline-flex", alignItems: "center", gap: "8px" }}>
              <Plus size={18} /> Add Expense
            </button>
          )}
        </div>

        {events.length > 0 ? (
          <select value={selectedEvent || ""} onChange={(e) => setSelectedEvent(e.target.value)} className="auth-input" style={{ maxWidth: "300px", marginBottom: "1.5rem" }}>
            {events.map((ev) => (<option key={ev.id} value={ev.id}>{ev.title}</option>))}
          </select>
        ) : (
          <p style={{ color: "rgba(0,0,0,0.5)", textAlign: "center", padding: "2rem" }}>Create an event first.</p>
        )}

        {selectedEvent && (
          <>
            {/* Budget Overview Cards */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: "12px", marginBottom: "1.5rem" }}>
              <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
                <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.75rem" }}>Total Budget</p>
                <h3 style={{ color: "#fbbf24", fontSize: "1.4rem" }}>₦{totalBudget.toLocaleString()}</h3>
              </div>
              <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
                <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.75rem" }}>Total Spent</p>
                <h3 style={{ color: "#ef4444", fontSize: "1.4rem" }}>₦{totalSpent.toLocaleString()}</h3>
              </div>
              <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
                <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.75rem" }}>Remaining</p>
                <h3 style={{ color: remaining >= 0 ? "#22c55e" : "#ef4444", fontSize: "1.4rem" }}>₦{remaining.toLocaleString()}</h3>
              </div>
              <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
                <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.75rem" }}>Pending Payments</p>
                <h3 style={{ color: "#f97316", fontSize: "1.4rem" }}>₦{totalPending.toLocaleString()}</h3>
              </div>
            </div>

            {/* Budget Progress Bar */}
            {totalBudget > 0 && (
              <div className="glass" style={{ padding: "16px", borderRadius: "12px", marginBottom: "1.5rem" }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "8px" }}>
                  <span style={{ color: "#000", fontSize: "0.85rem" }}>Budget Usage</span>
                  <span style={{ color: budgetPercent > 90 ? "#ef4444" : "#fbbf24", fontSize: "0.85rem", fontWeight: 600 }}>{budgetPercent.toFixed(1)}%</span>
                </div>
                <div style={{ width: "100%", height: "10px", background: "rgba(0,0,0,0.1)", borderRadius: "5px", overflow: "hidden" }}>
                  <div style={{ width: `${budgetPercent}%`, height: "100%", background: budgetPercent > 90 ? "#ef4444" : budgetPercent > 70 ? "#f97316" : "linear-gradient(90deg, #fbbf24, #d97706)", borderRadius: "5px", transition: "width 0.3s" }} />
                </div>
                {budgetPercent > 90 && (
                  <div style={{ display: "flex", alignItems: "center", gap: "6px", marginTop: "8px", color: "#ef4444", fontSize: "0.8rem" }}>
                    <AlertTriangle size={14} /> Warning: You are approaching your budget limit!
                  </div>
                )}
              </div>
            )}

            {/* Category Breakdown */}
            {Object.keys(categoryTotals).length > 0 && (
              <div className="glass" style={{ padding: "16px", borderRadius: "12px", marginBottom: "1.5rem" }}>
                <h4 style={{ color: "#fbbf24", marginBottom: "12px", fontSize: "0.9rem" }}>Spending by Category</h4>
                <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
                  {Object.entries(categoryTotals)
                    .sort((a, b) => b[1] - a[1])
                    .map(([cat, total]) => (
                      <div key={cat} style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                        <span style={{ fontSize: "1.2rem" }}>{categoryIcons[cat] || "📦"}</span>
                        <span style={{ color: "#000", fontSize: "0.85rem", minWidth: "120px" }}>{cat}</span>
                        <div style={{ flex: 1, height: "6px", background: "rgba(0,0,0,0.1)", borderRadius: "3px", overflow: "hidden" }}>
                          <div style={{ width: `${(total / totalSpent) * 100}%`, height: "100%", background: "#fbbf24", borderRadius: "3px" }} />
                        </div>
                        <span style={{ color: "#fbbf24", fontSize: "0.85rem", minWidth: "80px", textAlign: "right" }}>₦{total.toLocaleString()}</span>
                      </div>
                    ))}
                </div>
              </div>
            )}

            {/* Expenses List */}
            <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
              <h4 style={{ color: "#fbbf24", marginBottom: "12px", fontSize: "0.9rem" }}>All Expenses ({expenses.length})</h4>
              {expenses.length === 0 ? (
                <p style={{ color: "rgba(0,0,0,0.3)", textAlign: "center", padding: "2rem" }}>No expenses recorded yet.</p>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
                  {expenses.map((exp) => (
                    <div key={exp.id} style={{ display: "flex", alignItems: "center", gap: "12px", padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.03)", borderBottom: "1px solid rgba(0,0,0,0.05)" }}>
                      <span style={{ fontSize: "1.2rem" }}>{categoryIcons[exp.category] || "📦"}</span>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <p style={{ color: "#000", fontSize: "0.9rem", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{exp.title}</p>
                        <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.75rem" }}>{exp.category} {exp.vendor ? `• ${exp.vendor}` : ""}</p>
                      </div>
                      <span style={{ color: "#fbbf24", fontWeight: 600, fontSize: "0.9rem", whiteSpace: "nowrap" }}>₦{Number(exp.amount).toLocaleString()}</span>
                      <select
                        value={exp.status}
                        onChange={(e) => handleStatusChange(exp.id, e.target.value)}
                        style={{
                          padding: "4px 8px", borderRadius: "6px", background: "rgba(0,0,0,0.05)", border: "1px solid rgba(0,0,0,0.15)",
                          color: exp.status === "paid" ? "#22c55e" : exp.status === "overdue" ? "#ef4444" : "#fbbf24", fontSize: "0.75rem", cursor: "pointer",
                        }}
                      >
                        <option value="pending" style={{ background: "#ffffff" }}>Pending</option>
                        <option value="paid" style={{ background: "#ffffff" }}>Paid</option>
                        <option value="overdue" style={{ background: "#ffffff" }}>Overdue</option>
                      </select>
                      <button onClick={() => handleEdit(exp)} style={{ padding: "4px", borderRadius: "4px", background: "rgba(251,191,36,0.15)", border: "none", color: "#fbbf24", cursor: "pointer" }}><Edit3 size={14} /></button>
                      <button onClick={() => handleDelete(exp.id)} style={{ padding: "4px", borderRadius: "4px", background: "rgba(239,68,68,0.15)", border: "none", color: "#ef4444", cursor: "pointer" }}><Trash2 size={14} /></button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </>
        )}

        {/* Add/Edit Modal */}
        {showAdd && (
          <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.7)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000, padding: "1rem" }}>
            <form onSubmit={handleSubmit} className="glass" style={{ padding: "2rem", borderRadius: "16px", width: "100%", maxWidth: "450px" }}>
              <h3 style={{ color: "#fbbf24", marginBottom: "1rem" }}>{editingExpense ? "Edit Expense" : "Add Expense"}</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                <input className="auth-input" placeholder="Expense Title *" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} required />
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "10px" }}>
                  <input className="auth-input" type="number" placeholder="Amount (₦) *" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} required />
                  <select className="auth-input" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })}>
                    {categories.map((c) => (<option key={c} value={c} style={{ background: "#ffffff" }}>{c}</option>))}
                  </select>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "10px" }}>
                  <input className="auth-input" placeholder="Vendor Name" value={form.vendor} onChange={(e) => setForm({ ...form, vendor: e.target.value })} />
                  <select className="auth-input" value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })}>
                    <option value="pending" style={{ background: "#ffffff" }}>Pending</option>
                    <option value="paid" style={{ background: "#ffffff" }}>Paid</option>
                    <option value="overdue" style={{ background: "#ffffff" }}>Overdue</option>
                  </select>
                </div>
                <input className="auth-input" type="date" value={form.dueDate} onChange={(e) => setForm({ ...form, dueDate: e.target.value })} />
                <textarea className="auth-input auth-textarea" placeholder="Notes" value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} rows="2" />
              </div>
              <div style={{ display: "flex", gap: "10px", marginTop: "1rem" }}>
                <button type="submit" className="auth-submit" style={{ flex: 1 }}>{editingExpense ? "Update" : "Add Expense"}</button>
                <button type="button" onClick={() => { setShowAdd(false); setEditingExpense(null); }} style={{ flex: 1, padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.1)", color: "#000", border: "none", cursor: "pointer" }}>Cancel</button>
              </div>
            </form>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect } from "react";
import {
  collection,
  query,
  where,
  onSnapshot,
} from "firebase/firestore";
import { ChevronLeft, ChevronRight, Clock, MapPin, Calendar as CalendarIcon } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

const eventTypeColors = {
  wedding: "#fbbf24",
  birthday: "#ec4899",
  corporate: "#3b82f6",
  "baby-shower": "#8b5cf6",
  "bridal-shower": "#f472b6",
  conference: "#06b6d4",
  concert: "#ef4444",
  other: "#6b7280",
};

export default function CalendarView() {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [events, setEvents] = useState([]);
  const [selectedDay, setSelectedDay] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;
    const q = query(collection(db, "events"), where("userId", "==", uid));
    const unsub = onSnapshot(q, (snap) => {
      setEvents(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
      setLoading(false);
    });
    return unsub;
  }, []);

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const prevMonth = () => setCurrentDate(new Date(year, month - 1, 1));
  const nextMonth = () => setCurrentDate(new Date(year, month + 1, 1));
  const goToday = () => { setCurrentDate(new Date()); setSelectedDay(new Date().getDate()); };

  const eventsOnDay = (day) => {
    const dateStr = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    return events.filter((e) => e.date === dateStr);
  };

  const selectedDayEvents = selectedDay ? eventsOnDay(selectedDay) : [];
  const today = new Date();
  const isToday = (day) => today.getDate() === day && today.getMonth() === month && today.getFullYear() === year;

  const upcomingEvents = events
    .filter((e) => {
      if (!e.date) return false;
      const d = new Date(e.date);
      return d >= today;
    })
    .sort((a, b) => new Date(a.date) - new Date(b.date))
    .slice(0, 5);

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">Calendar</div>
            <h1>Event Calendar</h1>
            <p>View and manage your event schedule at a glance.</p>
          </div>
          <button onClick={goToday} style={{ padding: "8px 16px", borderRadius: "8px", background: "rgba(251,191,36,0.15)", border: "1px solid rgba(251,191,36,0.3)", color: "#fbbf24", cursor: "pointer", fontSize: "0.85rem" }}>
            Today
          </button>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 320px", gap: "20px" }}>
          {/* Calendar Grid */}
          <div className="glass" style={{ padding: "20px", borderRadius: "16px" }}>
            {/* Month Header */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
              <button onClick={prevMonth} style={{ padding: "8px", borderRadius: "8px", background: "rgba(0,0,0,0.05)", border: "none", color: "#000", cursor: "pointer" }}><ChevronLeft size={20} /></button>
              <h2 style={{ color: "#fbbf24", fontSize: "1.2rem" }}>{MONTHS[month]} {year}</h2>
              <button onClick={nextMonth} style={{ padding: "8px", borderRadius: "8px", background: "rgba(0,0,0,0.05)", border: "none", color: "#000", cursor: "pointer" }}><ChevronRight size={20} /></button>
            </div>

            {/* Day Headers */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: "4px", marginBottom: "8px" }}>
              {DAYS.map((d) => (
                <div key={d} style={{ textAlign: "center", padding: "8px 0", color: "rgba(0,0,0,0.4)", fontSize: "0.75rem", fontWeight: 600, textTransform: "uppercase" }}>{d}</div>
              ))}
            </div>

            {/* Day Cells */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: "4px" }}>
              {Array.from({ length: firstDay }).map((_, i) => (
                <div key={`empty-${i}`} style={{ aspectRatio: "1", borderRadius: "8px" }} />
              ))}
              {Array.from({ length: daysInMonth }).map((_, i) => {
                const day = i + 1;
                const dayEvents = eventsOnDay(day);
                const selected = selectedDay === day;
                const today = isToday(day);

                return (
                  <div
                    key={day}
                    onClick={() => setSelectedDay(selected ? null : day)}
                    style={{
                      aspectRatio: "1",
                      borderRadius: "8px",
                      padding: "4px",
                      cursor: "pointer",
                      background: selected ? "rgba(251,191,36,0.2)" : today ? "rgba(251,191,36,0.08)" : "rgba(0,0,0,0.03)",
                      border: today ? "2px solid #fbbf24" : selected ? "2px solid rgba(251,191,36,0.5)" : "2px solid transparent",
                      display: "flex",
                      flexDirection: "column",
                      alignItems: "center",
                      justifyContent: "center",
                      gap: "2px",
                      transition: "all 0.2s",
                    }}
                  >
                    <span style={{ color: today ? "#fbbf24" : "#000", fontSize: "0.85rem", fontWeight: today || selected ? 700 : 400 }}>{day}</span>
                    {dayEvents.length > 0 && (
                      <div style={{ display: "flex", gap: "2px" }}>
                        {dayEvents.slice(0, 3).map((e, idx) => (
                          <div key={idx} style={{ width: "5px", height: "5px", borderRadius: "50%", background: eventTypeColors[e.eventType] || "#fbbf24" }} />
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Sidebar */}
          <div style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
            {/* Selected Day Events */}
            {selectedDay && (
              <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
                <h3 style={{ color: "#fbbf24", fontSize: "0.95rem", marginBottom: "12px" }}>
                  {MONTHS[month]} {selectedDay}, {year}
                </h3>
                {selectedDayEvents.length === 0 ? (
                  <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.85rem" }}>No events on this day</p>
                ) : (
                  <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
                    {selectedDayEvents.map((ev) => (
                      <div key={ev.id} style={{ padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.05)", borderLeft: `3px solid ${eventTypeColors[ev.eventType] || "#fbbf24"}` }}>
                        <p style={{ color: "#000", fontWeight: 500, fontSize: "0.9rem" }}>{ev.title}</p>
                        {ev.location && <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.75rem", display: "flex", alignItems: "center", gap: "4px" }}><MapPin size={10} /> {ev.location}</p>}
                        <span style={{ padding: "2px 8px", borderRadius: "10px", background: `${eventTypeColors[ev.eventType] || "#fbbf24"}22`, color: eventTypeColors[ev.eventType] || "#fbbf24", fontSize: "0.7rem", textTransform: "capitalize" }}>{ev.eventType}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Upcoming Events */}
            <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
              <h3 style={{ color: "#fbbf24", fontSize: "0.95rem", marginBottom: "12px" }}>Upcoming Events</h3>
              {upcomingEvents.length === 0 ? (
                <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.85rem" }}>No upcoming events</p>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
                  {upcomingEvents.map((ev) => (
                    <div key={ev.id} style={{ display: "flex", alignItems: "center", gap: "10px", padding: "8px", borderRadius: "8px", background: "rgba(0,0,0,0.03)" }}>
                      <div style={{ width: "4px", height: "40px", borderRadius: "2px", background: eventTypeColors[ev.eventType] || "#fbbf24" }} />
                      <div>
                        <p style={{ color: "#000", fontSize: "0.85rem" }}>{ev.title}</p>
                        <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.75rem" }}><CalendarIcon size={10} /> {ev.date}</p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Legend */}
            <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
              <h3 style={{ color: "#fbbf24", fontSize: "0.95rem", marginBottom: "12px" }}>Legend</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
                {Object.entries(eventTypeColors).map(([type, color]) => (
                  <div key={type} style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                    <div style={{ width: "10px", height: "10px", borderRadius: "50%", background: color }} />
                    <span style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.8rem", textTransform: "capitalize" }}>{type}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect, useRef } from "react";
import {
  collection,
  query,
  where,
  orderBy,
  onSnapshot,
  addDoc,
  deleteDoc,
  doc,
  serverTimestamp,
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { Upload, Image, Video, Trash2, Download, Eye, Plus, X, Camera } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db, storage } from "../../firebase/firebase";

export default function OmaCloud() {
  const [events, setEvents] = useState([]);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [previewFile, setPreviewFile] = useState(null);
  const [filter, setFilter] = useState("all");
  const fileInputRef = useRef(null);

  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;
    const q = query(collection(db, "events"), where("userId", "==", uid));
    const unsub = onSnapshot(q, (snap) => {
      setEvents(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
      setLoading(false);
    });
    return unsub;
  }, []);

  useEffect(() => {
    if (!selectedEvent) return;
    const q = query(
      collection(db, "cloudFiles"),
      where("eventId", "==", selectedEvent),
      orderBy("createdAt", "desc")
    );
    const unsub = onSnapshot(q, (snap) => {
      setFiles(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    });
    return unsub;
  }, [selectedEvent]);

  const handleUpload = async (e) => {
    const fileList = e.target.files;
    if (!fileList || !selectedEvent || !auth.currentUser) return;

    setUploading(true);
    for (const file of fileList) {
      try {
        const storageRef = ref(storage, `omacloud/${selectedEvent}/${Date.now()}_${file.name}`);
        const snapshot = await uploadBytes(storageRef, file);
        const url = await getDownloadURL(snapshot.ref);

        const fileType = file.type.startsWith("image/") ? "image" : file.type.startsWith("video/") ? "video" : "other";

        await addDoc(collection(db, "cloudFiles"), {
          eventId: selectedEvent,
          userId: auth.currentUser.uid,
          fileName: file.name,
          fileUrl: url,
          fileType,
          fileSize: file.size,
          createdAt: serverTimestamp(),
        });
      } catch (err) {
        console.error("Upload failed:", err);
      }
    }
    setUploading(false);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleDelete = async (fileId) => {
    if (!window.confirm("Delete this file?")) return;
    await deleteDoc(doc(db, "cloudFiles", fileId));
  };

  const filteredFiles = files.filter((f) => filter === "all" || f.fileType === filter);

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">Oma Cloud</div>
            <h1>Event Gallery</h1>
            <p>Store, manage, and share your event photos and videos.</p>
          </div>
        </div>

        {/* Event Selector */}
        {events.length > 0 ? (
          <select value={selectedEvent || ""} onChange={(e) => setSelectedEvent(e.target.value)} className="auth-input" style={{ maxWidth: "300px", marginBottom: "1.5rem" }}>
            <option value="">Select an event</option>
            {events.map((ev) => (<option key={ev.id} value={ev.id}>{ev.title}</option>))}
          </select>
        ) : (
          <p style={{ color: "rgba(0,0,0,0.5)", textAlign: "center", padding: "2rem" }}>Create an event first.</p>
        )}

        {selectedEvent && (
          <>
            {/* Upload & Filter Bar */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.5rem", flexWrap: "wrap", gap: "12px" }}>
              <div style={{ display: "flex", gap: "8px" }}>
                {["all", "image", "video"].map((f) => (
                  <button key={f} onClick={() => setFilter(f)} style={{ padding: "6px 14px", borderRadius: "8px", border: filter === f ? "2px solid #fbbf24" : "1px solid rgba(0,0,0,0.15)", background: filter === f ? "rgba(251,191,36,0.15)" : "rgba(0,0,0,0.05)", color: "#000", cursor: "pointer", fontSize: "0.8rem", textTransform: "capitalize" }}>
                  {f === "all" ? "All" : f + "s"}
                </button>
              ))}
              </div>
              <div>
                <input ref={fileInputRef} type="file" multiple accept="image/*,video/*" onChange={handleUpload} style={{ display: "none" }} />
                <button onClick={() => fileInputRef.current?.click()} disabled={uploading} style={{ padding: "8px 16px", borderRadius: "8px", background: "linear-gradient(135deg, #fbbf24, #d97706)", border: "none", color: "#000", fontWeight: 600, cursor: "pointer", display: "flex", alignItems: "center", gap: "6px", fontSize: "0.85rem" }}>
                  <Upload size={16} /> {uploading ? "Uploading..." : "Upload Files"}
                </button>
              </div>
            </div>

            {/* Stats */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "12px", marginBottom: "1.5rem" }}>
              <div className="glass" style={{ padding: "14px", borderRadius: "10px", textAlign: "center" }}>
                <Image size={24} style={{ color: "#fbbf24", marginBottom: "4px" }} />
                <h3 style={{ color: "#000" }}>{files.filter((f) => f.fileType === "image").length}</h3>
                <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.75rem" }}>Photos</p>
              </div>
              <div className="glass" style={{ padding: "14px", borderRadius: "10px", textAlign: "center" }}>
                <Video size={24} style={{ color: "#3b82f6", marginBottom: "4px" }} />
                <h3 style={{ color: "#000" }}>{files.filter((f) => f.fileType === "video").length}</h3>
                <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.75rem" }}>Videos</p>
              </div>
              <div className="glass" style={{ padding: "14px", borderRadius: "10px", textAlign: "center" }}>
                <Camera size={24} style={{ color: "#22c55e", marginBottom: "4px" }} />
                <h3 style={{ color: "#000" }}>{files.length}</h3>
                <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.75rem" }}>Total Files</p>
              </div>
            </div>

            {/* Files Grid */}
            {filteredFiles.length === 0 ? (
              <div style={{ textAlign: "center", padding: "3rem", color: "rgba(0,0,0,0.3)" }}>
                <Upload size={48} style={{ marginBottom: "1rem", opacity: 0.3 }} />
                <p>No files uploaded yet. Upload photos and videos from your event.</p>
              </div>
            ) : (
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))", gap: "12px" }}>
                {filteredFiles.map((file) => (
                  <div key={file.id} className="glass" style={{ borderRadius: "12px", overflow: "hidden" }}>
                    {file.fileType === "image" ? (
                      <div style={{ height: "160px", overflow: "hidden", cursor: "pointer" }} onClick={() => setPreviewFile(file)}>
                        <img src={file.fileUrl} alt={file.fileName} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                      </div>
                    ) : (
                      <div style={{ height: "160px", background: "rgba(0,0,0,0.05)", display: "flex", alignItems: "center", justifyContent: "center" }}>
                        <Video size={40} style={{ color: "#3b82f6", opacity: 0.5 }} />
                      </div>
                    )}
                    <div style={{ padding: "10px" }}>
                      <p style={{ color: "#000", fontSize: "0.8rem", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{file.fileName}</p>
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "6px" }}>
                        <span style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.7rem" }}>{(file.fileSize / 1024 / 1024).toFixed(1)} MB</span>
                        <div style={{ display: "flex", gap: "4px" }}>
                          <a href={file.fileUrl} target="_blank" rel="noreferrer" style={{ padding: "4px", borderRadius: "4px", background: "rgba(59,130,246,0.15)", color: "#3b82f6", cursor: "pointer" }}><Download size={12} /></a>
                          <button onClick={() => handleDelete(file.id)} style={{ padding: "4px", borderRadius: "4px", background: "rgba(239,68,68,0.15)", border: "none", color: "#ef4444", cursor: "pointer" }}><Trash2 size={12} /></button>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </>
        )}

        {/* Preview Modal */}
        {previewFile && (
          <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.9)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000, padding: "2rem" }} onClick={() => setPreviewFile(null)}>
            <button onClick={() => setPreviewFile(null)} style={{ position: "absolute", top: "20px", right: "20px", padding: "8px", borderRadius: "8px", background: "rgba(0,0,0,0.1)", border: "none", color: "#000", cursor: "pointer" }}><X size={24} /></button>
            <img src={previewFile.fileUrl} alt={previewFile.fileName} style={{ maxWidth: "90%", maxHeight: "90%", borderRadius: "8px", objectFit: "contain" }} />
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect } from "react";
import {
  collection,
  query,
  orderBy,
  onSnapshot,
  addDoc,
  serverTimestamp,
  doc,
  updateDoc,
  arrayUnion,
  arrayRemove,
} from "firebase/firestore";
import { Users, BookOpen, Award, MessageSquare, Search, Plus, Heart, MessageCircle, Share2, TrendingUp } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

const categories = ["All", "Weddings", "Birthday", "Corporate", "Vendor Tips", "Planning", "Q&A"];
const certifications = [
  { name: "Event Planning 101", level: "Beginner", points: 100 },
  { name: "Vendor Management", level: "Intermediate", points: 200 },
  { name: "Budget Mastery", level: "Intermediate", points: 150 },
  { name: "Oma Certified Pro", level: "Advanced", points: 500 },
];

export default function Community() {
  const [activeTab, setActiveTab] = useState("feed");
  const [posts, setPosts] = useState([]);
  const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [showNewPost, setShowNewPost] = useState(false);
  const [newPost, setNewPost] = useState({ title: "", content: "", category: "Planning" });
  const [commentText, setCommentText] = useState({});

  useEffect(() => {
    const q = query(collection(db, "communityPosts"), orderBy("createdAt", "desc"));
    const unsub = onSnapshot(q, (snap) => {
      setPosts(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    });
    return unsub;
  }, []);

  const handleNewPost = async (e) => {
    e.preventDefault();
    if (!newPost.title || !newPost.content || !auth.currentUser) return;
    await addDoc(collection(db, "communityPosts"), {
      ...newPost,
      userId: auth.currentUser.uid,
      authorName: auth.currentUser.displayName || "Anonymous",
      likes: [],
      comments: [],
      createdAt: serverTimestamp(),
    });
    setNewPost({ title: "", content: "", category: "Planning" });
    setShowNewPost(false);
  };

  const handleLike = async (postId, likes) => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;
    const ref = doc(db, "communityPosts", postId);
    if (likes.includes(uid)) {
      await updateDoc(ref, { likes: arrayRemove(uid) });
    } else {
      await updateDoc(ref, { likes: arrayUnion(uid) });
    }
  };

  const handleComment = async (postId) => {
    const text = commentText[postId];
    if (!text?.trim() || !auth.currentUser) return;
    const ref = doc(db, "communityPosts", postId);
    await updateDoc(ref, {
      comments: arrayUnion({
        text: text.trim(),
        userId: auth.currentUser.uid,
        authorName: auth.currentUser.displayName || "Anonymous",
        createdAt: new Date().toISOString(),
      }),
    });
    setCommentText({ ...commentText, [postId]: "" });
  };

  const filteredPosts = posts.filter((p) => {
    const matchCat = selectedCategory === "All" || p.category === selectedCategory;
    const matchSearch = p.title?.toLowerCase().includes(search.toLowerCase()) || p.content?.toLowerCase().includes(search.toLowerCase());
    return matchCat && matchSearch;
  });

  const trendingPosts = [...posts].sort((a, b) => (b.likes?.length || 0) - (a.likes?.length || 0)).slice(0, 5);

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">Community</div>
            <h1>Community Hub</h1>
            <p>Connect, learn, and grow with the OMA Events community.</p>
          </div>
          {activeTab === "feed" && (
            <button onClick={() => setShowNewPost(true)} className="auth-submit" style={{ display: "inline-flex", alignItems: "center", gap: "8px" }}>
              <Plus size={18} /> New Post
            </button>
          )}
        </div>

        {/* Tabs */}
        <div style={{ display: "flex", gap: "8px", marginBottom: "1.5rem" }}>
          {[
            { id: "feed", label: "Discussion Feed", icon: <MessageSquare size={16} /> },
            { id: "learn", label: "Learning Hub", icon: <BookOpen size={16} /> },
            { id: "certs", label: "Certifications", icon: <Award size={16} /> },
            { id: "trending", label: "Trending", icon: <TrendingUp size={16} /> },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id)} style={{ padding: "8px 16px", borderRadius: "8px", border: activeTab === tab.id ? "2px solid #fbbf24" : "1px solid rgba(0,0,0,0.15)", background: activeTab === tab.id ? "rgba(251,191,36,0.15)" : "rgba(0,0,0,0.05)", color: "#000", cursor: "pointer", fontSize: "0.85rem", display: "flex", alignItems: "center", gap: "6px" }}>
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>

        {/* Discussion Feed */}
        {activeTab === "feed" && (
          <>
            <div style={{ display: "flex", gap: "12px", marginBottom: "1.5rem", flexWrap: "wrap" }}>
              <div style={{ position: "relative", flex: 1, minWidth: "200px" }}>
                <Search size={14} style={{ position: "absolute", left: "12px", top: "50%", transform: "translateY(-50%)", color: "rgba(0,0,0,0.3)" }} />
                <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search discussions..." className="auth-input" style={{ paddingLeft: "36px" }} />
              </div>
            </div>
            <div style={{ display: "flex", gap: "6px", marginBottom: "1.5rem", flexWrap: "wrap" }}>
              {categories.map((c) => (
                <button key={c} onClick={() => setSelectedCategory(c)} style={{ padding: "4px 12px", borderRadius: "20px", border: selectedCategory === c ? "2px solid #fbbf24" : "1px solid rgba(0,0,0,0.15)", background: selectedCategory === c ? "rgba(251,191,36,0.15)" : "rgba(0,0,0,0.05)", color: "#000", cursor: "pointer", fontSize: "0.75rem" }}>
                  {c}
                </button>
              ))}
            </div>

            {filteredPosts.map((post) => (
              <div key={post.id} className="glass" style={{ padding: "16px", borderRadius: "12px", marginBottom: "12px" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "12px" }}>
                  <div style={{ width: "36px", height: "36px", borderRadius: "50%", background: "linear-gradient(135deg, #fbbf24, #d97706)", display: "flex", alignItems: "center", justifyContent: "center", color: "#000", fontWeight: 700, fontSize: "0.8rem" }}>
                    {post.authorName?.charAt(0)?.toUpperCase()}
                  </div>
                  <div>
                    <p style={{ color: "#000", fontWeight: 500, fontSize: "0.9rem" }}>{post.authorName}</p>
                    <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.7rem" }}>{post.createdAt?.toDate?.().toLocaleDateString() || "Just now"}</p>
                  </div>
                  <span style={{ marginLeft: "auto", padding: "2px 10px", borderRadius: "20px", background: "rgba(251,191,36,0.1)", color: "#fbbf24", fontSize: "0.7rem" }}>{post.category}</span>
                </div>
                <h4 style={{ color: "#000", marginBottom: "8px" }}>{post.title}</h4>
                <p style={{ color: "rgba(0,0,0,0.6)", fontSize: "0.85rem", lineHeight: "1.6" }}>{post.content}</p>
                <div style={{ display: "flex", gap: "16px", marginTop: "12px", paddingTop: "12px", borderTop: "1px solid rgba(0,0,0,0.05)" }}>
                  <button onClick={() => handleLike(post.id, post.likes || [])} style={{ display: "flex", alignItems: "center", gap: "6px", background: "none", border: "none", color: (post.likes || []).includes(auth.currentUser?.uid) ? "#ef4444" : "rgba(0,0,0,0.4)", cursor: "pointer", fontSize: "0.85rem" }}>
                    <Heart size={16} fill={(post.likes || []).includes(auth.currentUser?.uid) ? "#ef4444" : "none"} /> {post.likes?.length || 0}
                  </button>
                  <button style={{ display: "flex", alignItems: "center", gap: "6px", background: "none", border: "none", color: "rgba(0,0,0,0.4)", cursor: "pointer", fontSize: "0.85rem" }}>
                    <MessageCircle size={16} /> {post.comments?.length || 0}
                  </button>
                  <button style={{ display: "flex", alignItems: "center", gap: "6px", background: "none", border: "none", color: "rgba(0,0,0,0.4)", cursor: "pointer", fontSize: "0.85rem" }}>
                    <Share2 size={16} /> Share
                  </button>
                </div>
                {/* Comments */}
                <div style={{ marginTop: "12px" }}>
                  {(post.comments || []).slice(-2).map((c, idx) => (
                    <div key={idx} style={{ padding: "8px 0", borderBottom: "1px solid rgba(0,0,0,0.03)" }}>
                      <p style={{ color: "#fbbf24", fontSize: "0.75rem", fontWeight: 600 }}>{c.authorName}</p>
                      <p style={{ color: "rgba(0,0,0,0.6)", fontSize: "0.8rem" }}>{c.text}</p>
                    </div>
                  ))}
                  <div style={{ display: "flex", gap: "8px", marginTop: "8px" }}>
                    <input
                      value={commentText[post.id] || ""}
                      onChange={(e) => setCommentText({ ...commentText, [post.id]: e.target.value })}
                      onKeyDown={(e) => e.key === "Enter" && handleComment(post.id)}
                      placeholder="Add a comment..."
                      style={{ flex: 1, padding: "6px 10px", borderRadius: "8px", background: "rgba(0,0,0,0.05)", border: "1px solid rgba(0,0,0,0.1)", color: "#000", fontSize: "0.8rem" }}
                    />
                    <button onClick={() => handleComment(post.id)} style={{ padding: "6px 12px", borderRadius: "8px", background: "#fbbf24", color: "#000", border: "none", cursor: "pointer", fontWeight: 600, fontSize: "0.8rem" }}>Post</button>
                  </div>
                </div>
              </div>
            ))}
          </>
        )}

        {/* Learning Hub */}
        {activeTab === "learn" && (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: "16px" }}>
            {[
              { title: "Wedding Planning Masterclass", desc: "Complete guide to planning luxury weddings", lessons: 12, duration: "4 hrs" },
              { title: "Vendor Negotiation Skills", desc: "How to get the best deals from vendors", lessons: 8, duration: "2.5 hrs" },
              { title: "Budget Optimization", desc: "Maximize value within your event budget", lessons: 10, duration: "3 hrs" },
              { title: "Event Marketing 101", desc: "Promote events and sell tickets effectively", lessons: 6, duration: "2 hrs" },
              { title: "Client Management", desc: "Build lasting relationships with clients", lessons: 7, duration: "2 hrs" },
              { title: "Oma AI Power User", desc: "Master OMA AI for event intelligence", lessons: 5, duration: "1.5 hrs" },
            ].map((course, i) => (
              <div key={i} className="glass" style={{ padding: "20px", borderRadius: "12px" }}>
                <BookOpen size={28} style={{ color: "#fbbf24", marginBottom: "10px" }} />
                <h3 style={{ color: "#000", fontSize: "1rem", marginBottom: "6px" }}>{course.title}</h3>
                <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.8rem", marginBottom: "12px" }}>{course.desc}</p>
                <div style={{ display: "flex", gap: "12px", marginBottom: "12px" }}>
                  <span style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.75rem" }}>{course.lessons} lessons</span>
                  <span style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.75rem" }}>{course.duration}</span>
                </div>
                <button style={{ width: "100%", padding: "8px", borderRadius: "8px", background: "rgba(251,191,36,0.15)", border: "1px solid rgba(251,191,36,0.3)", color: "#fbbf24", cursor: "pointer", fontSize: "0.85rem" }}>Start Learning</button>
              </div>
            ))}
          </div>
        )}

        {/* Certifications */}
        {activeTab === "certs" && (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(250px, 1fr))", gap: "16px" }}>
            {certifications.map((cert, i) => (
              <div key={i} className="glass" style={{ padding: "20px", borderRadius: "12px", textAlign: "center" }}>
                <Award size={40} style={{ color: "#fbbf24", marginBottom: "10px" }} />
                <h3 style={{ color: "#000", marginBottom: "4px" }}>{cert.name}</h3>
                <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.8rem", marginBottom: "8px" }}>{cert.level}</p>
                <p style={{ color: "#fbbf24", fontSize: "0.85rem", marginBottom: "12px" }}>{cert.points} points required</p>
                <button style={{ width: "100%", padding: "8px", borderRadius: "8px", background: "linear-gradient(135deg, #fbbf24, #d97706)", border: "none", color: "#000", fontWeight: 600, cursor: "pointer", fontSize: "0.85rem" }}>Enroll</button>
              </div>
            ))}
          </div>
        )}

        {/* Trending */}
        {activeTab === "trending" && (
          <div>
            <h3 style={{ color: "#fbbf24", marginBottom: "16px" }}>Trending Discussions</h3>
            {trendingPosts.map((post, i) => (
              <div key={post.id} className="glass" style={{ padding: "14px", borderRadius: "10px", marginBottom: "8px", display: "flex", alignItems: "center", gap: "12px" }}>
                <span style={{ color: "#fbbf24", fontWeight: 700, fontSize: "1.2rem", minWidth: "30px" }}>#{i + 1}</span>
                <div style={{ flex: 1 }}>
                  <p style={{ color: "#000", fontSize: "0.9rem" }}>{post.title}</p>
                  <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.75rem" }}>{post.authorName} • {post.likes?.length || 0} likes</p>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* New Post Modal */}
        {showNewPost && (
          <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.7)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000, padding: "1rem" }}>
            <form onSubmit={handleNewPost} className="glass" style={{ padding: "2rem", borderRadius: "16px", width: "100%", maxWidth: "500px" }}>
              <h3 style={{ color: "#fbbf24", marginBottom: "1rem" }}>New Discussion</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                <input className="auth-input" placeholder="Title" value={newPost.title} onChange={(e) => setNewPost({ ...newPost, title: e.target.value })} required />
                <select className="auth-input" value={newPost.category} onChange={(e) => setNewPost({ ...newPost, category: e.target.value })}>
                  {categories.filter((c) => c !== "All").map((c) => (<option key={c} value={c} style={{ background: "#ffffff" }}>{c}</option>))}
                </select>
                <textarea className="auth-input auth-textarea" placeholder="Share your thoughts..." value={newPost.content} onChange={(e) => setNewPost({ ...newPost, content: e.target.value })} rows="5" required />
              </div>
              <div style={{ display: "flex", gap: "10px", marginTop: "1rem" }}>
                <button type="submit" className="auth-submit" style={{ flex: 1 }}>Post</button>
                <button type="button" onClick={() => setShowNewPost(false)} style={{ flex: 1, padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.1)", color: "#000", border: "none", cursor: "pointer" }}>Cancel</button>
              </div>
            </form>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect } from "react";
import { collection, query, onSnapshot, where, orderBy, doc, updateDoc, serverTimestamp } from "firebase/firestore";
import { Building2, Users, Settings, CreditCard, BarChart3, Shield, Plus, Crown } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

export default function EnterpriseDashboard() {
  const [activeTab, setActiveTab] = useState("overview");
  const [team, setTeam] = useState([]);
  const [branches, setBranches] = useState([]);
  const [events, setEvents] = useState([]);

  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;

    const teamUnsub = onSnapshot(query(collection(db, "teamMembers"), where("orgId", "==", uid)), (snap) => {
      setTeam(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    });

    const branchUnsub = onSnapshot(query(collection(db, "branches"), where("orgId", "==", uid)), (snap) => {
      setBranches(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    });

    const eventsUnsub = onSnapshot(query(collection(db, "events"), where("userId", "==", uid), orderBy("createdAt", "desc")), (snap) => {
      setEvents(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    });

    return () => { teamUnsub(); branchUnsub(); eventsUnsub(); };
  }, []);

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge" style={{ display: "flex", alignItems: "center", gap: "6px" }}><Crown size={14} /> Enterprise</div>
            <h1>OMA Pro - Enterprise</h1>
            <p>Multi-team management, staff permissions, and enterprise billing.</p>
