                  <div style={{ flex: 1 }}>
                    <p style={{ color: "#000", fontSize: "0.9rem" }}>{member.name}</p>
                    <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.75rem" }}>{member.email}</p>
