import { useState, useEffect } from "react";
import {
  collection,
  query,
  where,
  onSnapshot,
  doc,
  updateDoc,
  deleteDoc,
  addDoc,
  serverTimestamp,
  arrayUnion,
  arrayRemove,
  getDocs,
} from "firebase/firestore";
import { Link } from "react-router-dom";
import { Plus, Calendar, MapPin, Trash2, Edit3, Eye, CheckCircle, Clock, XCircle, Copy, ChevronDown } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

const statusColors = {
  planning: "#fbbf24",
  "in-progress": "#3b82f6",
  completed: "#22c55e",
  cancelled: "#ef4444",
};

const statusIcons = {
  planning: <Clock size={14} />,
  "in-progress": <Eye size={14} />,
  completed: <CheckCircle size={14} />,
  cancelled: <XCircle size={14} />,
};

export default function EventList() {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("all");
  const [editingEvent, setEditingEvent] = useState(null);
  const [showChecklist, setShowChecklist] = useState(null);
  const [newCheckItem, setNewCheckItem] = useState("");
  const [newTask, setNewTask] = useState("");

  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;

    const q = query(collection(db, "events"), where("userId", "==", uid));
    const unsub = onSnapshot(q, (snap) => {
      const list = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      list.sort((a, b) => {
        const da = a.createdAt?.toDate?.() || new Date(0);
        const db = b.createdAt?.toDate?.() || new Date(0);
        return db - da;
      });
      setEvents(list);
      setLoading(false);
    });

    return unsub;
  }, []);

  const handleDelete = async (eventId) => {
    if (!window.confirm("Delete this event?")) return;
    await deleteDoc(doc(db, "events", eventId));
  };

  const handleStatusChange = async (eventId, newStatus) => {
    await updateDoc(doc(db, "events", eventId), {
      status: newStatus,
      updatedAt: serverTimestamp(),
    });
  };

  const handleDuplicate = async (event) => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;
    const { id, createdAt, updatedAt, ...rest } = event;
    await addDoc(collection(db, "events"), {
      ...rest,
      title: `${rest.title} (Copy)`,
      status: "planning",
      userId: uid,
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
    });
  };

  const handleUpdateEvent = async (e) => {
    e.preventDefault();
    if (!editingEvent) return;
    await updateDoc(doc(db, "events", editingEvent.id), {
      title: editingEvent.title,
      date: editingEvent.date,
      location: editingEvent.location,
      budget: Number(editingEvent.budget) || 0,
      description: editingEvent.description,
      eventType: editingEvent.eventType,
      updatedAt: serverTimestamp(),
    });
    setEditingEvent(null);
  };

  const handleAddCheckItem = async (eventId) => {
    if (!newCheckItem.trim()) return;
    await updateDoc(doc(db, "events", eventId), {
      checklist: arrayUnion({ text: newCheckItem.trim(), done: false, id: Date.now().toString() }),
      updatedAt: serverTimestamp(),
    });
    setNewCheckItem("");
  };

  const handleToggleCheckItem = async (eventId, item) => {
    const ev = events.find((e) => e.id === eventId);
    if (!ev) return;
    const updated = (ev.checklist || []).map((c) =>
      c.id === item.id ? { ...c, done: !c.done } : c
    );
    await updateDoc(doc(db, "events", eventId), {
      checklist: updated,
      updatedAt: serverTimestamp(),
    });
  };

  const handleAddTask = async (eventId) => {
    if (!newTask.trim()) return;
    await updateDoc(doc(db, "events", eventId), {
      tasks: arrayUnion({ text: newTask.trim(), done: false, id: Date.now().toString() }),
      updatedAt: serverTimestamp(),
    });
    setNewTask("");
  };

  const filtered = events.filter((e) => filter === "all" || e.status === filter);

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">Events</div>
            <h1>Your Events</h1>
            <p>Manage, track, and execute all your events from one place.</p>
          </div>
          <Link to="/events" className="auth-submit" style={{ textDecoration: "none", display: "inline-flex", alignItems: "center", gap: "8px" }}>
            <Plus size={18} /> New Event
          </Link>
        </div>

        {/* Filter Bar */}
        <div style={{ display: "flex", gap: "8px", marginBottom: "1.5rem", flexWrap: "wrap" }}>
          {["all", "planning", "in-progress", "completed", "cancelled"].map((s) => (
            <button
              key={s}
              onClick={() => setFilter(s)}
              style={{
                padding: "6px 16px",
                borderRadius: "8px",
                border: filter === s ? "2px solid #fbbf24" : "1px solid rgba(0,0,0,0.15)",
                background: filter === s ? "rgba(251,191,36,0.15)" : "rgba(0,0,0,0.05)",
                color: "#000",
                cursor: "pointer",
                fontSize: "0.85rem",
                textTransform: "capitalize",
              }}
            >
              {s === "all" ? "All" : s.replace("-", " ")}
            </button>
          ))}
        </div>

        {loading ? (
          <p style={{ color: "rgba(0,0,0,0.5)", textAlign: "center", padding: "2rem" }}>Loading events...</p>
        ) : filtered.length === 0 ? (
          <div style={{ textAlign: "center", padding: "3rem", color: "rgba(0,0,0,0.5)" }}>
            <Calendar size={48} style={{ marginBottom: "1rem", opacity: 0.3 }} />
            <p>No events found. <Link to="/events" style={{ color: "#fbbf24" }}>Create your first event</Link></p>
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
            {filtered.map((event) => (
              <div key={event.id} className="glass" style={{ padding: "1.25rem", borderRadius: "12px", borderLeft: `4px solid ${statusColors[event.status] || "#fbbf24"}` }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: "1rem" }}>
                  <div style={{ flex: 1, minWidth: "200px" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "4px" }}>
                      <h3 style={{ color: "#000", fontSize: "1.1rem" }}>{event.title}</h3>
                      <span style={{
                        padding: "2px 10px",
                        borderRadius: "20px",
                        fontSize: "0.75rem",
                        background: `${statusColors[event.status]}22`,
                        color: statusColors[event.status],
                        display: "flex",
                        alignItems: "center",
                        gap: "4px",
                      }}>
                        {statusIcons[event.status]} {event.status?.replace("-", " ")}
                      </span>
                    </div>
                    <div style={{ display: "flex", gap: "1rem", flexWrap: "wrap", color: "rgba(0,0,0,0.5)", fontSize: "0.85rem" }}>
                      {event.date && <span><Calendar size={14} /> {event.date}</span>}
                      {event.location && <span><MapPin size={14} /> {event.location}</span>}
                      {event.budget > 0 && <span>₦{Number(event.budget).toLocaleString()}</span>}
                    </div>
                    {event.description && (
                      <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.85rem", marginTop: "6px" }}>
                        {event.description.slice(0, 120)}{event.description.length > 120 ? "..." : ""}
                      </p>
                    )}
                  </div>

                  <div style={{ display: "flex", gap: "6px", flexWrap: "wrap" }}>
                    {/* Status dropdown */}
                    <select
                      value={event.status}
                      onChange={(e) => handleStatusChange(event.id, e.target.value)}
                      style={{ padding: "6px", borderRadius: "6px", background: "#ffffff", color: "#000", border: "1px solid rgba(0,0,0,0.15)", fontSize: "0.8rem" }}
                    >
                      <option value="planning">Planning</option>
                      <option value="in-progress">In Progress</option>
                      <option value="completed">Completed</option>
                      <option value="cancelled">Cancelled</option>
                    </select>

                    <button onClick={() => setEditingEvent(event)} title="Edit" style={{ padding: "6px", borderRadius: "6px", background: "rgba(251,191,36,0.15)", border: "none", color: "#fbbf24", cursor: "pointer" }}>
                      <Edit3 size={16} />
                    </button>
                    <button onClick={() => handleDuplicate(event)} title="Duplicate" style={{ padding: "6px", borderRadius: "6px", background: "rgba(59,130,246,0.15)", border: "none", color: "#3b82f6", cursor: "pointer" }}>
                      <Copy size={16} />
                    </button>
                    <button onClick={() => setShowChecklist(showChecklist === event.id ? null : event.id)} title="Checklist" style={{ padding: "6px", borderRadius: "6px", background: "rgba(34,197,94,0.15)", border: "none", color: "#22c55e", cursor: "pointer" }}>
                      <CheckCircle size={16} />
                    </button>
                    <button onClick={() => handleDelete(event.id)} title="Delete" style={{ padding: "6px", borderRadius: "6px", background: "rgba(239,68,68,0.15)", border: "none", color: "#ef4444", cursor: "pointer" }}>
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>

                {/* Checklist & Tasks Panel */}
                {showChecklist === event.id && (
                  <div style={{ marginTop: "1rem", paddingTop: "1rem", borderTop: "1px solid rgba(0,0,0,0.1)" }}>
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "1.5rem" }}>
                      {/* Checklist */}
                      <div>
                        <h4 style={{ color: "#fbbf24", marginBottom: "8px", fontSize: "0.9rem" }}>Checklist</h4>
                        {(event.checklist || []).map((item, idx) => (
                          <div key={idx} style={{ display: "flex", alignItems: "center", gap: "8px", padding: "4px 0" }}>
                            <input
                              type="checkbox"
                              checked={item.done}
                              onChange={() => handleToggleCheckItem(event.id, item)}
                              style={{ accentColor: "#fbbf24" }}
                            />
                            <span style={{ color: item.done ? "rgba(0,0,0,0.3)" : "#000", textDecoration: item.done ? "line-through" : "none", fontSize: "0.85rem" }}>
                              {item.text}
                            </span>
                          </div>
                        ))}
                        <div style={{ display: "flex", gap: "6px", marginTop: "8px" }}>
                          <input
                            value={newCheckItem}
                            onChange={(e) => setNewCheckItem(e.target.value)}
                            onKeyDown={(e) => e.key === "Enter" && handleAddCheckItem(event.id)}
                            placeholder="Add item..."
                            style={{ flex: 1, padding: "6px 10px", borderRadius: "6px", background: "rgba(0,0,0,0.05)", border: "1px solid rgba(0,0,0,0.15)", color: "#000", fontSize: "0.85rem" }}
                          />
                          <button onClick={() => handleAddCheckItem(event.id)} style={{ padding: "6px 12px", borderRadius: "6px", background: "#fbbf24", color: "#000", border: "none", cursor: "pointer", fontWeight: 600 }}>+</button>
                        </div>
                      </div>

                      {/* Tasks */}
                      <div>
                        <h4 style={{ color: "#fbbf24", marginBottom: "8px", fontSize: "0.9rem" }}>Tasks</h4>
                        {(event.tasks || []).map((item, idx) => (
                          <div key={idx} style={{ display: "flex", alignItems: "center", gap: "8px", padding: "4px 0" }}>
                            <input
                              type="checkbox"
                              checked={item.done}
                              onChange={async () => {
                                const updated = (event.tasks || []).map((t) => t.id === item.id ? { ...t, done: !t.done } : t);
                                await updateDoc(doc(db, "events", event.id), { tasks: updated, updatedAt: serverTimestamp() });
                              }}
                              style={{ accentColor: "#fbbf24" }}
                            />
                            <span style={{ color: item.done ? "rgba(0,0,0,0.3)" : "#000", textDecoration: item.done ? "line-through" : "none", fontSize: "0.85rem" }}>
                              {item.text}
                            </span>
                          </div>
                        ))}
                        <div style={{ display: "flex", gap: "6px", marginTop: "8px" }}>
                          <input
                            value={newTask}
                            onChange={(e) => setNewTask(e.target.value)}
                            onKeyDown={(e) => e.key === "Enter" && handleAddTask(event.id)}
                            placeholder="Add task..."
                            style={{ flex: 1, padding: "6px 10px", borderRadius: "6px", background: "rgba(0,0,0,0.05)", border: "1px solid rgba(0,0,0,0.15)", color: "#000", fontSize: "0.85rem" }}
                          />
                          <button onClick={() => handleAddTask(event.id)} style={{ padding: "6px 12px", borderRadius: "6px", background: "#fbbf24", color: "#000", border: "none", cursor: "pointer", fontWeight: 600 }}>+</button>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        {/* Edit Modal */}
        {editingEvent && (
          <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.7)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000, padding: "1rem" }}>
            <form onSubmit={handleUpdateEvent} className="glass" style={{ padding: "2rem", borderRadius: "16px", width: "100%", maxWidth: "500px", maxHeight: "90vh", overflow: "auto" }}>
              <h3 style={{ color: "#fbbf24", marginBottom: "1rem" }}>Edit Event</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                <input className="auth-input" placeholder="Title" value={editingEvent.title} onChange={(e) => setEditingEvent({ ...editingEvent, title: e.target.value })} />
                <input className="auth-input" type="date" value={editingEvent.date} onChange={(e) => setEditingEvent({ ...editingEvent, date: e.target.value })} />
                <input className="auth-input" type="number" placeholder="Budget" value={editingEvent.budget} onChange={(e) => setEditingEvent({ ...editingEvent, budget: e.target.value })} />
                <input className="auth-input" placeholder="Location" value={editingEvent.location} onChange={(e) => setEditingEvent({ ...editingEvent, location: e.target.value })} />
                <select className="auth-input" value={editingEvent.eventType} onChange={(e) => setEditingEvent({ ...editingEvent, eventType: e.target.value })}>
                  <option value="wedding">Wedding</option>
                  <option value="birthday">Birthday</option>
                  <option value="corporate">Corporate</option>
                  <option value="baby-shower">Baby Shower</option>
                  <option value="bridal-shower">Bridal Shower</option>
                  <option value="conference">Conference</option>
                  <option value="other">Other</option>
                </select>
                <textarea className="auth-input auth-textarea" placeholder="Description" value={editingEvent.description} onChange={(e) => setEditingEvent({ ...editingEvent, description: e.target.value })} rows="3" />
              </div>
              <div style={{ display: "flex", gap: "10px", marginTop: "1rem" }}>
                <button type="submit" className="auth-submit" style={{ flex: 1 }}>Save Changes</button>
                <button type="button" onClick={() => setEditingEvent(null)} style={{ flex: 1, padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.1)", color: "#000", border: "none", cursor: "pointer" }}>Cancel</button>
              </div>
            </form>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect } from "react";
import {
  collection,
  query,
  where,
  onSnapshot,
  addDoc,
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp,
} from "firebase/firestore";
import { Users, UserPlus, Trash2, Mail, Phone, CheckCircle, XCircle, Edit3, Search } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

const rsvpOptions = ["invited", "confirmed", "declined", "pending"];

export default function GuestManagement() {
  const [events, setEvents] = useState([]);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [guests, setGuests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [showAdd, setShowAdd] = useState(false);
  const [editingGuest, setEditingGuest] = useState(null);
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    group: "General",
    rsvp: "invited",
    plusOne: false,
    notes: "",
  });

  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;
    const q = query(collection(db, "events"), where("userId", "==", uid));
    const unsub = onSnapshot(q, (snap) => {
      const list = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      setEvents(list);
      setSelectedEvent((current) => current ?? list[0]?.id ?? null);
      setLoading(false);
    });
    return unsub;
  }, []);

  useEffect(() => {
    if (!selectedEvent) return;
    const q = query(collection(db, "guests"), where("eventId", "==", selectedEvent));
    const unsub = onSnapshot(q, (snap) => {
      const list = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      setGuests(list);
    });
    return unsub;
  }, [selectedEvent]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name.trim() || !selectedEvent) return;
    if (editingGuest) {
      await updateDoc(doc(db, "guests", editingGuest.id), {
        ...form,
        updatedAt: serverTimestamp(),
      });
      setEditingGuest(null);
    } else {
      await addDoc(collection(db, "guests"), {
        ...form,
        eventId: selectedEvent,
        userId: auth.currentUser.uid,
        createdAt: serverTimestamp(),
      });
    }
    setForm({ name: "", email: "", phone: "", group: "General", rsvp: "invited", plusOne: false, notes: "" });
    setShowAdd(false);
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Remove this guest?")) return;
    await deleteDoc(doc(db, "guests", id));
  };

  const handleRsvpChange = async (guestId, newRsvp) => {
    await updateDoc(doc(db, "guests", guestId), { rsvp: newRsvp, updatedAt: serverTimestamp() });
  };

  const handleEdit = (guest) => {
    setEditingGuest(guest);
    setForm({
      name: guest.name,
      email: guest.email || "",
      phone: guest.phone || "",
      group: guest.group || "General",
      rsvp: guest.rsvp || "invited",
      plusOne: guest.plusOne || false,
      notes: guest.notes || "",
    });
    setShowAdd(true);
  };

  const filtered = guests.filter((g) => {
    const q = search.toLowerCase();
    return (
      g.name?.toLowerCase().includes(q) ||
      g.email?.toLowerCase().includes(q) ||
      g.group?.toLowerCase().includes(q)
    );
  });

  const rsvpCounts = {
    invited: guests.filter((g) => g.rsvp === "invited").length,
    confirmed: guests.filter((g) => g.rsvp === "confirmed").length,
    declined: guests.filter((g) => g.rsvp === "declined").length,
    pending: guests.filter((g) => g.rsvp === "pending").length,
  };

  const groups = [...new Set(guests.map((g) => g.group || "General"))];

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">Guest Management</div>
            <h1>Guest List</h1>
            <p>Manage invitations, RSVPs, and seating for your events.</p>
          </div>
          {selectedEvent && (
            <button
              onClick={() => { setShowAdd(true); setEditingGuest(null); setForm({ name: "", email: "", phone: "", group: "General", rsvp: "invited", plusOne: false, notes: "" }); }}
              className="auth-submit"
              style={{ textDecoration: "none", display: "inline-flex", alignItems: "center", gap: "8px" }}
            >
              <UserPlus size={18} /> Add Guest
            </button>
          )}
        </div>

        {/* Event Selector */}
        {events.length > 0 ? (
          <select
            value={selectedEvent || ""}
            onChange={(e) => setSelectedEvent(e.target.value)}
            className="auth-input"
            style={{ maxWidth: "300px", marginBottom: "1.5rem" }}
          >
            {events.map((ev) => (
              <option key={ev.id} value={ev.id}>{ev.title}</option>
            ))}
          </select>
        ) : (
          <p style={{ color: "rgba(0,0,0,0.5)", textAlign: "center", padding: "2rem" }}>Create an event first to manage guests.</p>
        )}

        {selectedEvent && (
          <>
            {/* RSVP Stats */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(120px, 1fr))", gap: "10px", marginBottom: "1.5rem" }}>
              {rsvpOptions.map((r) => (
                <div key={r} className="glass" style={{ padding: "12px", borderRadius: "10px", textAlign: "center" }}>
                  <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.75rem", textTransform: "capitalize" }}>{r}</p>
                  <h3 style={{ color: "#fbbf24", fontSize: "1.5rem" }}>{rsvpCounts[r]}</h3>
                </div>
              ))}
            </div>

            {/* Groups */}
            <div style={{ display: "flex", gap: "8px", marginBottom: "1rem", flexWrap: "wrap" }}>
              {groups.map((g) => (
                <span key={g} style={{ padding: "4px 12px", borderRadius: "20px", background: "rgba(251,191,36,0.1)", color: "#fbbf24", fontSize: "0.8rem" }}>
                  {g} ({guests.filter((x) => x.group === g).length})
                </span>
              ))}
            </div>

            {/* Search */}
            <div style={{ position: "relative", marginBottom: "1rem" }}>
              <Search size={16} style={{ position: "absolute", left: "12px", top: "50%", transform: "translateY(-50%)", color: "rgba(0,0,0,0.3)" }} />
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search guests by name, email, or group..."
                className="auth-input"
                style={{ paddingLeft: "36px" }}
              />
            </div>

            {/* Guest Table */}
            {filtered.length === 0 ? (
              <div style={{ textAlign: "center", padding: "3rem", color: "rgba(0,0,0,0.3)" }}>
                <Users size={48} style={{ marginBottom: "1rem", opacity: 0.3 }} />
                <p>No guests yet. Add your first guest!</p>
              </div>
            ) : (
              <div style={{ overflowX: "auto" }}>
                <table style={{ width: "100%", borderCollapse: "collapse", color: "#000" }}>
                  <thead>
                    <tr style={{ borderBottom: "1px solid rgba(0,0,0,0.1)" }}>
                      <th style={{ textAlign: "left", padding: "10px", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>Name</th>
                      <th style={{ textAlign: "left", padding: "10px", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>Email</th>
                      <th style={{ textAlign: "left", padding: "10px", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>Phone</th>
                      <th style={{ textAlign: "left", padding: "10px", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>Group</th>
                      <th style={{ textAlign: "left", padding: "10px", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>RSVP</th>
                      <th style={{ textAlign: "left", padding: "10px", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>+1</th>
                      <th style={{ textAlign: "right", padding: "10px", color: "rgba(0,0,0,0.5)", fontSize: "0.8rem" }}>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filtered.map((guest) => (
                      <tr key={guest.id} style={{ borderBottom: "1px solid rgba(0,0,0,0.05)" }}>
                        <td style={{ padding: "10px", fontSize: "0.9rem" }}>{guest.name}</td>
                        <td style={{ padding: "10px", fontSize: "0.85rem", color: "rgba(0,0,0,0.5)" }}>{guest.email || "—"}</td>
                        <td style={{ padding: "10px", fontSize: "0.85rem", color: "rgba(0,0,0,0.5)" }}>{guest.phone || "—"}</td>
                        <td style={{ padding: "10px" }}>
                          <span style={{ padding: "2px 8px", borderRadius: "10px", background: "rgba(251,191,36,0.1)", color: "#fbbf24", fontSize: "0.75rem" }}>
                            {guest.group}
                          </span>
                        </td>
                        <td style={{ padding: "10px" }}>
                          <select
                            value={guest.rsvp}
                            onChange={(e) => handleRsvpChange(guest.id, e.target.value)}
                            style={{
                              padding: "4px 8px",
                              borderRadius: "6px",
                              background: "rgba(0,0,0,0.05)",
                              border: "1px solid rgba(0,0,0,0.15)",
                              color: guest.rsvp === "confirmed" ? "#22c55e" : guest.rsvp === "declined" ? "#ef4444" : "#fbbf24",
                              fontSize: "0.8rem",
                              cursor: "pointer",
                            }}
                          >
                            {rsvpOptions.map((r) => (
                              <option key={r} value={r} style={{ background: "#ffffff" }}>{r}</option>
                            ))}
                          </select>
                        </td>
                        <td style={{ padding: "10px", color: guest.plusOne ? "#22c55e" : "rgba(0,0,0,0.3)" }}>
                          {guest.plusOne ? <CheckCircle size={16} /> : <XCircle size={16} />}
                        </td>
                        <td style={{ padding: "10px", textAlign: "right" }}>
                          <div style={{ display: "flex", gap: "4px", justifyContent: "flex-end" }}>
                            <button onClick={() => handleEdit(guest)} style={{ padding: "4px", borderRadius: "4px", background: "rgba(251,191,36,0.15)", border: "none", color: "#fbbf24", cursor: "pointer" }}>
                              <Edit3 size={14} />
                            </button>
                            <button onClick={() => handleDelete(guest.id)} style={{ padding: "4px", borderRadius: "4px", background: "rgba(239,68,68,0.15)", border: "none", color: "#ef4444", cursor: "pointer" }}>
                              <Trash2 size={14} />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </>
        )}

        {/* Add/Edit Modal */}
        {showAdd && (
          <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.7)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000, padding: "1rem" }}>
            <form onSubmit={handleSubmit} className="glass" style={{ padding: "2rem", borderRadius: "16px", width: "100%", maxWidth: "450px" }}>
              <h3 style={{ color: "#fbbf24", marginBottom: "1rem" }}>{editingGuest ? "Edit Guest" : "Add Guest"}</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                <input className="auth-input" placeholder="Full Name *" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required />
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "10px" }}>
                  <input className="auth-input" type="email" placeholder="Email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
                  <input className="auth-input" type="tel" placeholder="Phone" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} />
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "10px" }}>
                  <input className="auth-input" placeholder="Group (e.g. Family, VIP)" value={form.group} onChange={(e) => setForm({ ...form, group: e.target.value })} />
                  <select className="auth-input" value={form.rsvp} onChange={(e) => setForm({ ...form, rsvp: e.target.value })}>
                    {rsvpOptions.map((r) => (
                      <option key={r} value={r} style={{ background: "#ffffff" }}>{r}</option>
                    ))}
                  </select>
                </div>
                <label style={{ display: "flex", alignItems: "center", gap: "8px", color: "#000", fontSize: "0.9rem" }}>
                  <input type="checkbox" checked={form.plusOne} onChange={(e) => setForm({ ...form, plusOne: e.target.checked })} style={{ accentColor: "#fbbf24" }} />
                  Allow +1
                </label>
                <textarea className="auth-input auth-textarea" placeholder="Notes (dietary, seating, etc.)" value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} rows="2" />
              </div>
              <div style={{ display: "flex", gap: "10px", marginTop: "1rem" }}>
                <button type="submit" className="auth-submit" style={{ flex: 1 }}>{editingGuest ? "Update" : "Add Guest"}</button>
                <button type="button" onClick={() => { setShowAdd(false); setEditingGuest(null); }} style={{ flex: 1, padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.1)", color: "#000", border: "none", cursor: "pointer" }}>Cancel</button>
              </div>
            </form>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect, useRef } from "react";
import {
  collection,
  query,
  where,
  orderBy,
  onSnapshot,
  addDoc,
  serverTimestamp,
  doc,
  setDoc,
  getDoc,
} from "firebase/firestore";
import { Send, Search, Plus, Image, Paperclip, Smile } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

export default function Messaging() {
  const [conversations, setConversations] = useState([]);
  const [activeChat, setActiveChat] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState("");
  const [search, setSearch] = useState("");
  const [showNewChat, setShowNewChat] = useState(false);
  const [chatSearch, setChatSearch] = useState("");
  const messagesEndRef = useRef(null);

  const uid = auth.currentUser?.uid;

  useEffect(() => {
    if (!uid) return;
    const q = query(
      collection(db, "conversations"),
      where("participants", "array-contains", uid),
      orderBy("lastMessageTime", "desc")
    );
    const unsub = onSnapshot(q, (snap) => {
      setConversations(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    });
    return unsub;
  }, [uid]);

  useEffect(() => {
    if (!activeChat) return;
    const q = query(
      collection(db, "messages"),
      where("conversationId", "==", activeChat),
      orderBy("createdAt", "asc")
    );
    const unsub = onSnapshot(q, (snap) => {
      setMessages(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    });
    return unsub;
  }, [activeChat]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSend = async (e) => {
    e.preventDefault();
    if (!newMessage.trim() || !activeChat || !uid) return;

    await addDoc(collection(db, "messages"), {
      conversationId: activeChat,
      senderId: uid,
      text: newMessage.trim(),
      createdAt: serverTimestamp(),
    });

    await setDoc(
      doc(db, "conversations", activeChat),
      { lastMessage: newMessage.trim(), lastMessageTime: serverTimestamp() },
      { merge: true }
    );

    setNewMessage("");
  };

  const handleNewConversation = async (otherUserId, otherUserName) => {
    if (!uid) return;
    const convId = [uid, otherUserId].sort().join("_");

    const existing = await getDoc(doc(db, "conversations", convId));
    if (existing.exists()) {
      setActiveChat(convId);
      setShowNewChat(false);
      return;
    }

    await setDoc(doc(db, "conversations", convId), {
      participants: [uid, otherUserId],
      participantNames: {
        [uid]: auth.currentUser?.displayName || "You",
        [otherUserId]: otherUserName,
      },
      lastMessage: "",
      lastMessageTime: serverTimestamp(),
      createdAt: serverTimestamp(),
    });

    setActiveChat(convId);
    setShowNewChat(false);
  };

  const filteredConvs = conversations.filter((c) => {
    const otherName = Object.entries(c.participantNames || {})
      .filter(([k]) => k !== uid)
      .map(([, v]) => v)
      .join(", ");
    return otherName.toLowerCase().includes(search.toLowerCase());
  });

  const activeConvo = conversations.find((c) => c.id === activeChat);
  const activeChatName = activeConvo
    ? Object.entries(activeConvo.participantNames || {})
        .filter(([k]) => k !== uid)
        .map(([, v]) => v)
        .join(", ") || "Unknown"
    : "";

  return (
    <DashboardLayout>
      <div style={{ display: "flex", height: "calc(100vh - 60px)", overflow: "hidden" }}>
        {/* Sidebar: Conversations */}
        <div style={{ width: "320px", borderRight: "1px solid rgba(0,0,0,0.1)", display: "flex", flexDirection: "column", background: "rgba(0,0,0,0.02)" }}>
          <div style={{ padding: "16px", borderBottom: "1px solid rgba(0,0,0,0.1)" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "12px" }}>
              <h2 style={{ color: "#fbbf24", fontSize: "1.1rem" }}>Messages</h2>
              <button onClick={() => setShowNewChat(!showNewChat)} style={{ padding: "6px", borderRadius: "6px", background: "rgba(251,191,36,0.15)", border: "none", color: "#fbbf24", cursor: "pointer" }}>
                <Plus size={18} />
              </button>
            </div>
            <div style={{ position: "relative" }}>
              <Search size={14} style={{ position: "absolute", left: "10px", top: "50%", transform: "translateY(-50%)", color: "rgba(0,0,0,0.3)" }} />
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search conversations..."
                style={{ width: "100%", padding: "8px 10px 8px 32px", borderRadius: "8px", background: "rgba(0,0,0,0.05)", border: "1px solid rgba(0,0,0,0.1)", color: "#000", fontSize: "0.85rem" }}
              />
            </div>
          </div>

          <div style={{ flex: 1, overflowY: "auto" }}>
            {filteredConvs.length === 0 ? (
              <p style={{ color: "rgba(0,0,0,0.3)", textAlign: "center", padding: "2rem", fontSize: "0.85rem" }}>No conversations yet</p>
            ) : (
              filteredConvs.map((conv) => {
                const otherName = Object.entries(conv.participantNames || {})
                  .filter(([k]) => k !== uid)
                  .map(([, v]) => v)
                  .join(", ");
                return (
                  <div
                    key={conv.id}
                    onClick={() => setActiveChat(conv.id)}
                    style={{
                      padding: "12px 16px",
                      cursor: "pointer",
                      background: activeChat === conv.id ? "rgba(251,191,36,0.1)" : "transparent",
                      borderLeft: activeChat === conv.id ? "3px solid #fbbf24" : "3px solid transparent",
                      transition: "all 0.2s",
                    }}
                  >
                    <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                      <div style={{ width: "36px", height: "36px", borderRadius: "50%", background: "linear-gradient(135deg, #fbbf24, #d97706)", display: "flex", alignItems: "center", justifyContent: "center", color: "#000", fontWeight: 700, fontSize: "0.85rem" }}>
                        {otherName.charAt(0).toUpperCase()}
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <p style={{ color: "#000", fontSize: "0.9rem", fontWeight: 500, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{otherName}</p>
                        <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.75rem", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{conv.lastMessage || "Start a conversation"}</p>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Main: Chat Area */}
        <div style={{ flex: 1, display: "flex", flexDirection: "column" }}>
          {!activeChat ? (
            <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", color: "rgba(0,0,0,0.3)" }}>
              <div style={{ textAlign: "center" }}>
                <Send size={48} style={{ marginBottom: "1rem", opacity: 0.3 }} />
                <p>Select a conversation to start messaging</p>
              </div>
            </div>
          ) : (
            <>
              {/* Chat Header */}
              <div style={{ padding: "12px 20px", borderBottom: "1px solid rgba(0,0,0,0.1)", display: "flex", alignItems: "center", gap: "10px" }}>
                <div style={{ width: "32px", height: "32px", borderRadius: "50%", background: "linear-gradient(135deg, #fbbf24, #d97706)", display: "flex", alignItems: "center", justifyContent: "center", color: "#000", fontWeight: 700, fontSize: "0.8rem" }}>
                  {activeChatName.charAt(0).toUpperCase()}
                </div>
                <div>
                  <p style={{ color: "#000", fontWeight: 500 }}>{activeChatName}</p>
                  <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.75rem" }}>Online</p>
                </div>
              </div>

              {/* Messages */}
              <div style={{ flex: 1, overflowY: "auto", padding: "20px", display: "flex", flexDirection: "column", gap: "8px" }}>
                {messages.map((msg) => {
                  const isMine = msg.senderId === uid;
                  return (
                    <div key={msg.id} style={{ display: "flex", justifyContent: isMine ? "flex-end" : "flex-start" }}>
                      <div style={{
                        maxWidth: "70%",
                        padding: "10px 14px",
                        borderRadius: isMine ? "14px 14px 4px 14px" : "14px 14px 14px 4px",
                        background: isMine ? "linear-gradient(135deg, #fbbf24, #d97706)" : "rgba(0,0,0,0.08)",
                        color: isMine ? "#000" : "#000",
                        fontSize: "0.9rem",
                      }}>
                        {msg.text}
                      </div>
                    </div>
                  );
                })}
                <div ref={messagesEndRef} />
              </div>

              {/* Message Input */}
              <form onSubmit={handleSend} style={{ padding: "12px 20px", borderTop: "1px solid rgba(0,0,0,0.1)", display: "flex", gap: "10px", alignItems: "center" }}>
                <button type="button" style={{ padding: "8px", borderRadius: "8px", background: "rgba(0,0,0,0.05)", border: "none", color: "rgba(0,0,0,0.4)", cursor: "pointer" }}>
                  <Paperclip size={18} />
                </button>
                <input
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  placeholder="Type a message..."
                  style={{ flex: 1, padding: "10px 14px", borderRadius: "10px", background: "rgba(0,0,0,0.05)", border: "1px solid rgba(0,0,0,0.1)", color: "#000", fontSize: "0.9rem" }}
                />
                <button type="button" style={{ padding: "8px", borderRadius: "8px", background: "rgba(0,0,0,0.05)", border: "none", color: "rgba(0,0,0,0.4)", cursor: "pointer" }}>
                  <Smile size={18} />
                </button>
                <button type="submit" style={{ padding: "10px 16px", borderRadius: "10px", background: "linear-gradient(135deg, #fbbf24, #d97706)", border: "none", color: "#000", cursor: "pointer", fontWeight: 600, display: "flex", alignItems: "center", gap: "6px" }}>
                  <Send size={16} />
                </button>
              </form>
            </>
          )}
        </div>
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect } from "react";
import {
  collection,
  query,
  where,
  orderBy,
  onSnapshot,
  doc,
  updateDoc,
  deleteDoc,
  serverTimestamp,
} from "firebase/firestore";
import { Bell, Check, Trash2, Filter } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

const typeIcons = {
  event: "📅",
  booking: "🎫",
  payment: "💰",
  alert: "⚠️",
  message: "💬",
  system: "⚙️",
};

const typeColors = {
  event: "#fbbf24",
  booking: "#3b82f6",
  payment: "#22c55e",
  alert: "#ef4444",
  message: "#8b5cf6",
  system: "#6b7280",
};

export default function Notifications() {
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("all");

  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;

    const q = query(
      collection(db, "notifications"),
      where("userId", "==", uid),
      orderBy("createdAt", "desc")
    );

    const unsub = onSnapshot(q, (snap) => {
      setNotifications(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
      setLoading(false);
    });

    return unsub;
  }, []);

  const handleMarkRead = async (id) => {
    await updateDoc(doc(db, "notifications", id), {
      read: true,
      readAt: serverTimestamp(),
    });
  };

  const handleMarkAllRead = async () => {
    const unread = notifications.filter((n) => !n.read);
    for (const n of unread) {
      await updateDoc(doc(db, "notifications", n.id), {
        read: true,
        readAt: serverTimestamp(),
      });
    }
  };

  const handleDelete = async (id) => {
    await deleteDoc(doc(db, "notifications", id));
  };

  const handleClearAll = async () => {
    if (!window.confirm("Delete all notifications?")) return;
    for (const n of notifications) {
      await deleteDoc(doc(db, "notifications", n.id));
    }
  };

  const filtered = notifications.filter((n) => {
    if (filter === "all") return true;
    if (filter === "unread") return !n.read;
    return n.type === filter;
  });

  const unreadCount = notifications.filter((n) => !n.read).length;

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">Notifications</div>
            <h1>Notifications</h1>
            <p>Stay updated on events, bookings, and platform activity.</p>
          </div>
          <div style={{ display: "flex", gap: "8px" }}>
            {unreadCount > 0 && (
              <button onClick={handleMarkAllRead} style={{ padding: "8px 16px", borderRadius: "8px", background: "rgba(34,197,94,0.15)", border: "1px solid rgba(34,197,94,0.3)", color: "#22c55e", cursor: "pointer", fontSize: "0.85rem", display: "flex", alignItems: "center", gap: "6px" }}>
                <Check size={16} /> Mark All Read ({unreadCount})
              </button>
            )}
            <button onClick={handleClearAll} style={{ padding: "8px 16px", borderRadius: "8px", background: "rgba(239,68,68,0.15)", border: "1px solid rgba(239,68,68,0.3)", color: "#ef4444", cursor: "pointer", fontSize: "0.85rem", display: "flex", alignItems: "center", gap: "6px" }}>
              <Trash2 size={16} /> Clear All
            </button>
          </div>
        </div>

        {/* Filters */}
        <div style={{ display: "flex", gap: "8px", marginBottom: "1.5rem", flexWrap: "wrap" }}>
          {["all", "unread", "event", "booking", "payment", "alert", "message", "system"].map((f) => (
            <button key={f} onClick={() => setFilter(f)} style={{ padding: "6px 14px", borderRadius: "20px", border: filter === f ? "2px solid #fbbf24" : "1px solid rgba(0,0,0,0.15)", background: filter === f ? "rgba(251,191,36,0.15)" : "rgba(0,0,0,0.05)", color: "#000", cursor: "pointer", fontSize: "0.8rem", textTransform: "capitalize" }}>
              {f === "all" ? `All (${notifications.length})` : f === "unread" ? `Unread (${unreadCount})` : `${f} (${notifications.filter((n) => n.type === f).length})`}
            </button>
          ))}
        </div>

        {/* Notifications List */}
        {loading ? (
          <p style={{ color: "rgba(0,0,0,0.5)", textAlign: "center", padding: "2rem" }}>Loading notifications...</p>
        ) : filtered.length === 0 ? (
          <div style={{ textAlign: "center", padding: "4rem", color: "rgba(0,0,0,0.3)" }}>
            <Bell size={48} style={{ marginBottom: "1rem", opacity: 0.3 }} />
            <p>No notifications to show.</p>
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
            {filtered.map((notif) => (
              <div
                key={notif.id}
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: "12px",
                  padding: "14px 16px",
                  borderRadius: "10px",
                  background: notif.read ? "rgba(0,0,0,0.02)" : "rgba(251,191,36,0.05)",
                  border: notif.read ? "1px solid rgba(0,0,0,0.05)" : "1px solid rgba(251,191,36,0.15)",
                  cursor: "pointer",
                }}
                onClick={() => !notif.read && handleMarkRead(notif.id)}
              >
                <span style={{ fontSize: "1.3rem" }}>{typeIcons[notif.type] || "📌"}</span>
                <div style={{ flex: 1 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "2px" }}>
                    <h4 style={{ color: "#000", fontSize: "0.9rem", fontWeight: notif.read ? 400 : 600 }}>{notif.title}</h4>
                    {!notif.read && <div style={{ width: "6px", height: "6px", borderRadius: "50%", background: "#fbbf24" }} />}
                  </div>
                  <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.85rem" }}>{notif.message}</p>
                  <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.7rem", marginTop: "4px" }}>
                    {notif.createdAt?.toDate?.().toLocaleString() || "Just now"}
                  </p>
                </div>
                <button
                  onClick={(e) => { e.stopPropagation(); handleDelete(notif.id); }}
                  style={{ padding: "4px", borderRadius: "4px", background: "rgba(239,68,68,0.1)", border: "none", color: "#ef4444", cursor: "pointer", flexShrink: 0 }}
                >
                  <Trash2 size={14} />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect } from "react";
import {
  collection,
  query,
  where,
  orderBy,
  onSnapshot,
  addDoc,
  doc,
  serverTimestamp,
  updateDoc,
} from "firebase/firestore";
import { Wallet, ArrowUpRight, ArrowDownLeft, Clock, CheckCircle, AlertCircle, Send, Plus, Eye, EyeOff, CreditCard, Lock, TrendingUp } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

const transactionTypes = {
  credit: { color: "#22c55e", icon: <ArrowDownLeft size={16} /> },
  debit: { color: "#ef4444", icon: <ArrowUpRight size={16} /> },
  escrow: { color: "#fbbf24", icon: <Lock size={16} /> },
};

const statusColors = {
  completed: "#22c55e",
  pending: "#f97316",
  failed: "#ef4444",
};

export default function OmaPay() {
  const [wallet, setWallet] = useState({ balance: 0, escrow: 0 });
  const [transactions, setTransactions] = useState([]);
  const [escrowPayments, setEscrowPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showFund, setShowFund] = useState(false);
  const [showPay, setShowPay] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [fundAmount, setFundAmount] = useState("");
  const [payForm, setPayForm] = useState({ recipient: "", amount: "", description: "" });
  const [showBalance, setShowBalance] = useState(true);

  const uid = auth.currentUser?.uid;

  useEffect(() => {
    if (!uid) return;

    const walletUnsub = onSnapshot(doc(db, "wallets", uid), (snap) => {
      if (snap.exists()) {
        setWallet(snap.data());
      }
      setLoading(false);
    });

    const txUnsub = onSnapshot(
      query(collection(db, "transactions"), where("userId", "==", uid), orderBy("createdAt", "desc")),
      (snap) => setTransactions(snap.docs.map((d) => ({ id: d.id, ...d.data() })))
    );

    const escrowUnsub = onSnapshot(
      query(collection(db, "escrow"), where("userId", "==", uid), orderBy("createdAt", "desc")),
      (snap) => setEscrowPayments(snap.docs.map((d) => ({ id: d.id, ...d.data() })))
    );

    return () => { walletUnsub(); txUnsub(); escrowUnsub(); };
  }, [uid]);

  const handleFund = async (e) => {
    e.preventDefault();
    if (!fundAmount || !uid) return;
    const amount = Number(fundAmount);
    if (amount <= 0) return;

    const newBalance = (wallet.balance || 0) + amount;

    await updateDoc(doc(db, "wallets", uid), {
      balance: newBalance,
      updatedAt: serverTimestamp(),
    });

    await addDoc(collection(db, "transactions"), {
      userId: uid,
      type: "credit",
      amount,
      description: "Wallet Funding",
      status: "completed",
      createdAt: serverTimestamp(),
    });

    setFundAmount("");
    setShowFund(false);
  };

  const handlePay = async (e) => {
    e.preventDefault();
    if (!payForm.recipient || !payForm.amount || !uid) return;
    const amount = Number(payForm.amount);
    if (amount <= 0 || amount > wallet.balance) return;

    const newBalance = wallet.balance - amount;

    await updateDoc(doc(db, "wallets", uid), {
      balance: newBalance,
      updatedAt: serverTimestamp(),
    });

    await addDoc(collection(db, "transactions"), {
      userId: uid,
      type: "debit",
      amount,
      description: payForm.description || `Payment to ${payForm.recipient}`,
      recipient: payForm.recipient,
      status: "completed",
      createdAt: serverTimestamp(),
    });

    setPayForm({ recipient: "", amount: "", description: "" });
    setShowPay(false);
  };

  const handleEscrow = async (vendorName, amount, eventId) => {
    if (!uid) return;
    await addDoc(collection(db, "escrow"), {
      userId: uid,
      vendorName,
      eventId,
      amount: Number(amount),
      status: "held",
      createdAt: serverTimestamp(),
    });

    const newBalance = wallet.balance - Number(amount);
    await updateDoc(doc(db, "wallets", uid), { balance: newBalance, updatedAt: serverTimestamp() });

    await addDoc(collection(db, "transactions"), {
      userId: uid,
      type: "escrow",
      amount: Number(amount),
      description: `Escrow for ${vendorName}`,
      status: "pending",
      createdAt: serverTimestamp(),
    });
  };

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">OmaPay</div>
            <h1>Payments & Wallet</h1>
            <p>Manage your wallet, make payments, and track transactions.</p>
          </div>
        </div>

        {/* Wallet Overview */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: "16px", marginBottom: "1.5rem" }}>
          <div className="glass" style={{ padding: "20px", borderRadius: "16px", background: "linear-gradient(135deg, rgba(251,191,36,0.1), rgba(217,119,6,0.05))" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "12px" }}>
              <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.85rem" }}>Wallet Balance</p>
              <button onClick={() => setShowBalance(!showBalance)} style={{ background: "none", border: "none", color: "rgba(0,0,0,0.3)", cursor: "pointer" }}>
                {showBalance ? <Eye size={16} /> : <EyeOff size={16} />}
              </button>
            </div>
            <h2 style={{ color: "#fbbf24", fontSize: "2rem" }}>
              {showBalance ? `₦${(wallet.balance || 0).toLocaleString()}` : "••••••"}
            </h2>
            <div style={{ display: "flex", gap: "8px", marginTop: "12px" }}>
              <button onClick={() => setShowFund(true)} style={{ flex: 1, padding: "8px", borderRadius: "8px", background: "linear-gradient(135deg, #fbbf24, #d97706)", border: "none", color: "#000", fontWeight: 600, cursor: "pointer", fontSize: "0.85rem" }}>Fund Wallet</button>
              <button onClick={() => setShowPay(true)} style={{ flex: 1, padding: "8px", borderRadius: "8px", background: "rgba(0,0,0,0.08)", border: "1px solid rgba(0,0,0,0.15)", color: "#000", cursor: "pointer", fontSize: "0.85rem" }}>Send Money</button>
            </div>
          </div>

          <div className="glass" style={{ padding: "20px", borderRadius: "16px" }}>
            <div style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "8px" }}>
              <Lock size={16} style={{ color: "#fbbf24" }} />
              <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.85rem" }}>In Escrow</p>
            </div>
            <h2 style={{ color: "#f97316", fontSize: "1.5rem" }}>₦{(wallet.escrow || 0).toLocaleString()}</h2>
            <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.75rem", marginTop: "4px" }}>Protected payments</p>
          </div>

          <div className="glass" style={{ padding: "20px", borderRadius: "16px" }}>
            <div style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "8px" }}>
              <TrendingUp size={16} style={{ color: "#22c55e" }} />
              <p style={{ color: "rgba(0,0,0,0.5)", fontSize: "0.85rem" }}>Total Spent</p>
            </div>
            <h2 style={{ color: "#22c55e", fontSize: "1.5rem" }}>
              ₦{transactions.filter((t) => t.type === "debit").reduce((s, t) => s + (t.amount || 0), 0).toLocaleString()}
            </h2>
          </div>
        </div>

        {/* Tab Navigation */}
        <div style={{ display: "flex", gap: "8px", marginBottom: "1.5rem" }}>
          {["overview", "transactions", "escrow"].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab)} style={{ padding: "8px 16px", borderRadius: "8px", border: activeTab === tab ? "2px solid #fbbf24" : "1px solid rgba(0,0,0,0.15)", background: activeTab === tab ? "rgba(251,191,36,0.15)" : "rgba(0,0,0,0.05)", color: "#000", cursor: "pointer", fontSize: "0.85rem", textTransform: "capitalize" }}>
              {tab}
            </button>
          ))}
        </div>

        {/* Transactions */}
        {(activeTab === "overview" || activeTab === "transactions") && (
          <div className="glass" style={{ padding: "16px", borderRadius: "12px", marginBottom: "1.5rem" }}>
            <h3 style={{ color: "#fbbf24", marginBottom: "12px", fontSize: "0.95rem" }}>Recent Transactions</h3>
            {transactions.length === 0 ? (
              <p style={{ color: "rgba(0,0,0,0.3)", textAlign: "center", padding: "2rem" }}>No transactions yet</p>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: "4px" }}>
                {transactions.slice(0, activeTab === "overview" ? 5 : transactions.length).map((tx) => (
                  <div key={tx.id} style={{ display: "flex", alignItems: "center", gap: "12px", padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.03)" }}>
                    <div style={{ width: "32px", height: "32px", borderRadius: "8px", background: `${transactionTypes[tx.type]?.color || "#fbbf24"}22`, display: "flex", alignItems: "center", justifyContent: "center", color: transactionTypes[tx.type]?.color || "#fbbf24" }}>
                      {transactionTypes[tx.type]?.icon || <CreditCard size={16} />}
                    </div>
                    <div style={{ flex: 1 }}>
                      <p style={{ color: "#000", fontSize: "0.85rem" }}>{tx.description}</p>
                      <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.7rem" }}>{tx.createdAt?.toDate?.().toLocaleDateString() || "—"}</p>
                    </div>
                    <span style={{ color: tx.type === "credit" ? "#22c55e" : "#fbbf24", fontWeight: 600, fontSize: "0.9rem" }}>
                      {tx.type === "credit" ? "+" : "-"}₦{(tx.amount || 0).toLocaleString()}
                    </span>
                    <span style={{ padding: "2px 8px", borderRadius: "10px", background: `${statusColors[tx.status] || "#fbbf24"}22`, color: statusColors[tx.status] || "#fbbf24", fontSize: "0.7rem" }}>
                      {tx.status}
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Escrow */}
        {(activeTab === "overview" || activeTab === "escrow") && (
          <div className="glass" style={{ padding: "16px", borderRadius: "12px" }}>
            <h3 style={{ color: "#fbbf24", marginBottom: "12px", fontSize: "0.95rem" }}>Escrow Payments</h3>
            {escrowPayments.length === 0 ? (
              <p style={{ color: "rgba(0,0,0,0.3)", textAlign: "center", padding: "2rem" }}>No escrow payments</p>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: "4px" }}>
                {escrowPayments.map((ep) => (
                  <div key={ep.id} style={{ display: "flex", alignItems: "center", gap: "12px", padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.03)" }}>
                    <Lock size={16} style={{ color: "#fbbf24" }} />
                    <div style={{ flex: 1 }}>
                      <p style={{ color: "#000", fontSize: "0.85rem" }}>{ep.vendorName}</p>
                      <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.7rem" }}>Escrow hold</p>
                    </div>
                    <span style={{ color: "#f97316", fontWeight: 600 }}>₦{(ep.amount || 0).toLocaleString()}</span>
                    <span style={{ padding: "2px 8px", borderRadius: "10px", background: `${ep.status === "released" ? "#22c55e" : ep.status === "disputed" ? "#ef4444" : "#f97316"}22`, color: ep.status === "released" ? "#22c55e" : ep.status === "disputed" ? "#ef4444" : "#f97316", fontSize: "0.7rem", textTransform: "capitalize" }}>
                      {ep.status}
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Fund Modal */}
        {showFund && (
          <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.7)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000, padding: "1rem" }}>
            <form onSubmit={handleFund} className="glass" style={{ padding: "2rem", borderRadius: "16px", width: "100%", maxWidth: "400px" }}>
              <h3 style={{ color: "#fbbf24", marginBottom: "1rem" }}>Fund Wallet</h3>
              <input className="auth-input" type="number" placeholder="Amount (₦)" value={fundAmount} onChange={(e) => setFundAmount(e.target.value)} required />
              <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.75rem", marginTop: "8px" }}>In production, this integrates with Paystack/Flutterwave for card/bank transfers.</p>
              <div style={{ display: "flex", gap: "10px", marginTop: "1rem" }}>
                <button type="submit" className="auth-submit" style={{ flex: 1 }}>Fund Wallet</button>
                <button type="button" onClick={() => setShowFund(false)} style={{ flex: 1, padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.1)", color: "#000", border: "none", cursor: "pointer" }}>Cancel</button>
              </div>
            </form>
          </div>
        )}

        {/* Pay Modal */}
        {showPay && (
          <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.7)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000, padding: "1rem" }}>
            <form onSubmit={handlePay} className="glass" style={{ padding: "2rem", borderRadius: "16px", width: "100%", maxWidth: "400px" }}>
              <h3 style={{ color: "#fbbf24", marginBottom: "1rem" }}>Send Money</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                <input className="auth-input" placeholder="Recipient (name or email)" value={payForm.recipient} onChange={(e) => setPayForm({ ...payForm, recipient: e.target.value })} required />
                <input className="auth-input" type="number" placeholder="Amount (₦)" value={payForm.amount} onChange={(e) => setPayForm({ ...payForm, amount: e.target.value })} required />
                <input className="auth-input" placeholder="Description" value={payForm.description} onChange={(e) => setPayForm({ ...payForm, description: e.target.value })} />
              </div>
              {payForm.amount && Number(payForm.amount) > (wallet.balance || 0) && (
                <p style={{ color: "#ef4444", fontSize: "0.8rem", marginTop: "8px" }}>Insufficient balance. Your balance is ₦{(wallet.balance || 0).toLocaleString()}</p>
              )}
              <div style={{ display: "flex", gap: "10px", marginTop: "1rem" }}>
                <button type="submit" disabled={Number(payForm.amount) > (wallet.balance || 0)} className="auth-submit" style={{ flex: 1, opacity: Number(payForm.amount) > (wallet.balance || 0) ? 0.5 : 1 }}>Send Payment</button>
                <button type="button" onClick={() => setShowPay(false)} style={{ flex: 1, padding: "10px", borderRadius: "8px", background: "rgba(0,0,0,0.1)", color: "#000", border: "none", cursor: "pointer" }}>Cancel</button>
              </div>
            </form>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

import { useState, useEffect } from "react";
import {
  collection,
  query,
  orderBy,
  onSnapshot,
  addDoc,
  serverTimestamp,
  doc,
  updateDoc,
  arrayUnion,
  arrayRemove,
} from "firebase/firestore";
import { Heart, MessageCircle, Share2, Bookmark, TrendingUp, Search, Plus, Star, Users } from "lucide-react";
import DashboardLayout from "../../components/layout/DashboardLayout";
import { auth, db } from "../../firebase/firebase";

const trendingTags = ["#WeddingInspo", "#AfricanWedding", "#EventPlanning", "#DecorIdeas", "#LagosEvents", "#AbujaVibes"];

const mockTrending = [
  { tag: "#TrendingWeddings", posts: 234 },
  { tag: "#BirthdayGoals", posts: 189 },
  { tag: "#CorporateEvents", posts: 156 },
  { tag: "#EventDecor", posts: 142 },
];

export default function SocialFeed() {
  const [posts, setPosts] = useState([]);
  const [activeTab, setActiveTab] = useState("feed");
  const [newPost, setNewPost] = useState("");
  const [newPostType, setNewPostType] = useState("highlight");
  const [showNewPost, setShowNewPost] = useState(false);
  const [search, setSearch] = useState("");

  useEffect(() => {
    const q = query(collection(db, "socialPosts"), orderBy("createdAt", "desc"));
    const unsub = onSnapshot(q, (snap) => {
      setPosts(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    });
    return unsub;
  }, []);

  const handleNewPost = async (e) => {
    e.preventDefault();
    if (!newPost.trim() || !auth.currentUser) return;
    await addDoc(collection(db, "socialPosts"), {
      content: newPost.trim(),
      type: newPostType,
      userId: auth.currentUser.uid,
      authorName: auth.currentUser.displayName || "Anonymous",
      likes: [],
      comments: [],
      shares: 0,
      createdAt: serverTimestamp(),
    });
    setNewPost("");
    setShowNewPost(false);
  };

  const handleLike = async (postId, likes) => {
    const uid = auth.currentUser?.uid;
    if (!uid) return;
    const ref = doc(db, "socialPosts", postId);
    if (likes.includes(uid)) {
      await updateDoc(ref, { likes: arrayRemove(uid) });
    } else {
      await updateDoc(ref, { likes: arrayUnion(uid) });
    }
  };

  return (
    <DashboardLayout>
      <div className="dashboard-page">
        <div className="dashboard-topbar">
          <div className="dashboard-header">
            <div className="dashboard-badge">Social</div>
            <h1>Event Community</h1>
            <p>Share highlights, discover trends, and connect with event enthusiasts.</p>
          </div>
        </div>

        {/* Tabs */}
        <div style={{ display: "flex", gap: "8px", marginBottom: "1.5rem" }}>
          {[
            { id: "feed", label: "Feed", icon: <TrendingUp size={16} /> },
            { id: "discover", label: "Discover", icon: <Search size={16} /> },
            { id: "trending", label: "Trending", icon: <Star size={16} /> },
          ].map((tab) => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id)} style={{ padding: "8px 16px", borderRadius: "8px", border: activeTab === tab.id ? "2px solid #fbbf24" : "1px solid rgba(0,0,0,0.15)", background: activeTab === tab.id ? "rgba(251,191,36,0.15)" : "rgba(0,0,0,0.05)", color: "#000", cursor: "pointer", fontSize: "0.85rem", display: "flex", alignItems: "center", gap: "6px" }}>
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>

        {/* Feed */}
        {activeTab === "feed" && (
          <>
            {/* New Post */}
            <div className="glass" style={{ padding: "16px", borderRadius: "12px", marginBottom: "1.5rem" }}>
              <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                <div style={{ width: "36px", height: "36px", borderRadius: "50%", background: "linear-gradient(135deg, #fbbf24, #d97706)", display: "flex", alignItems: "center", justifyContent: "center", color: "#000", fontWeight: 700, fontSize: "0.8rem" }}>
                  {auth.currentUser?.displayName?.charAt(0)?.toUpperCase() || "U"}
                </div>
                <input
                  value={newPost}
                  onChange={(e) => setNewPost(e.target.value)}
                  placeholder="Share an event highlight, success story, or tip..."
                  style={{ flex: 1, padding: "10px 14px", borderRadius: "10px", background: "rgba(0,0,0,0.05)", border: "1px solid rgba(0,0,0,0.1)", color: "#000", fontSize: "0.9rem" }}
                  onFocus={() => setShowNewPost(true)}
                />
                {newPost && (
                  <button onClick={handleNewPost} style={{ padding: "8px 16px", borderRadius: "8px", background: "linear-gradient(135deg, #fbbf24, #d97706)", border: "none", color: "#000", fontWeight: 600, cursor: "pointer" }}>
                    Post
                  </button>
                )}
              </div>
              {showNewPost && (
                <div style={{ marginTop: "10px", display: "flex", gap: "8px" }}>
                  {["highlight", "success-story", "tip", "question"].map((type) => (
                    <button key={type} onClick={() => setNewPostType(type)} style={{ padding: "4px 10px", borderRadius: "20px", border: newPostType === type ? "2px solid #fbbf24" : "1px solid rgba(0,0,0,0.15)", background: newPostType === type ? "rgba(251,191,36,0.15)" : "transparent", color: "#000", cursor: "pointer", fontSize: "0.7rem", textTransform: "capitalize" }}>
                      {type.replace("-", " ")}
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Posts */}
            {posts.map((post) => (
              <div key={post.id} className="glass" style={{ padding: "16px", borderRadius: "12px", marginBottom: "12px" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "12px" }}>
                  <div style={{ width: "36px", height: "36px", borderRadius: "50%", background: "linear-gradient(135deg, #fbbf24, #d97706)", display: "flex", alignItems: "center", justifyContent: "center", color: "#000", fontWeight: 700, fontSize: "0.8rem" }}>
                    {post.authorName?.charAt(0)?.toUpperCase()}
                  </div>
                  <div style={{ flex: 1 }}>
                    <p style={{ color: "#000", fontWeight: 500, fontSize: "0.9rem" }}>{post.authorName}</p>
                    <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.7rem" }}>{post.createdAt?.toDate?.().toLocaleDateString() || "Just now"}</p>
                  </div>
                  <span style={{ padding: "2px 10px", borderRadius: "20px", background: "rgba(251,191,36,0.1)", color: "#fbbf24", fontSize: "0.7rem", textTransform: "capitalize" }}>{post.type?.replace("-", " ")}</span>
                </div>
                <p style={{ color: "rgba(0,0,0,0.8)", fontSize: "0.9rem", lineHeight: "1.6", marginBottom: "12px" }}>{post.content}</p>
                <div style={{ display: "flex", gap: "20px", paddingTop: "12px", borderTop: "1px solid rgba(0,0,0,0.05)" }}>
                  <button onClick={() => handleLike(post.id, post.likes || [])} style={{ display: "flex", alignItems: "center", gap: "6px", background: "none", border: "none", color: (post.likes || []).includes(auth.currentUser?.uid) ? "#ef4444" : "rgba(0,0,0,0.4)", cursor: "pointer", fontSize: "0.85rem" }}>
                    <Heart size={16} fill={(post.likes || []).includes(auth.currentUser?.uid) ? "#ef4444" : "none"} /> {post.likes?.length || 0}
                  </button>
                  <button style={{ display: "flex", alignItems: "center", gap: "6px", background: "none", border: "none", color: "rgba(0,0,0,0.4)", cursor: "pointer", fontSize: "0.85rem" }}>
                    <MessageCircle size={16} /> {post.comments?.length || 0}
                  </button>
                  <button style={{ display: "flex", alignItems: "center", gap: "6px", background: "none", border: "none", color: "rgba(0,0,0,0.4)", cursor: "pointer", fontSize: "0.85rem" }}>
                    <Share2 size={16} /> Share
                  </button>
                </div>
              </div>
            ))}
          </>
        )}

        {/* Discover */}
        {activeTab === "discover" && (
          <>
            <div style={{ position: "relative", marginBottom: "1.5rem" }}>
              <Search size={16} style={{ position: "absolute", left: "12px", top: "50%", transform: "translateY(-50%)", color: "rgba(0,0,0,0.3)" }} />
              <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search events, vendors, planners..." className="auth-input" style={{ paddingLeft: "36px" }} />
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(250px, 1fr))", gap: "16px" }}>
              {["Trending Weddings", "Top Decorators", "Best Caterers", "Event Venues", "Photography", "Event Planners"].map((topic, i) => (
                <div key={i} className="glass" style={{ padding: "20px", borderRadius: "12px" }}>
                  <TrendingUp size={24} style={{ color: "#fbbf24", marginBottom: "8px" }} />
                  <h4 style={{ color: "#000", marginBottom: "4px" }}>{topic}</h4>
                  <p style={{ color: "rgba(0,0,0,0.4)", fontSize: "0.8rem" }}>{Math.floor(Math.random() * 500 + 100)} posts</p>
                </div>
              ))}
            </div>
          </>
        )}

        {/* Trending */}
        {activeTab === "trending" && (
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px" }}>
            <div>
              <h3 style={{ color: "#fbbf24", marginBottom: "12px" }}>Trending Tags</h3>
              {trendingTags.map((tag) => (
                <div key={tag} className="glass" style={{ padding: "12px", borderRadius: "8px", marginBottom: "8px", display: "flex", alignItems: "center", gap: "10px", cursor: "pointer" }}>
                  <HashIcon />
                  <div>
                    <p style={{ color: "#000", fontSize: "0.9rem" }}>{tag}</p>
                    <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.75rem" }}>{Math.floor(Math.random() * 1000 + 200)} posts</p>
                  </div>
                </div>
              ))}
            </div>
            <div>
              <h3 style={{ color: "#fbbf24", marginBottom: "12px" }}>Trending Events</h3>
              {mockTrending.map((item, i) => (
                <div key={i} className="glass" style={{ padding: "12px", borderRadius: "8px", marginBottom: "8px", display: "flex", alignItems: "center", gap: "10px" }}>
                  <span style={{ color: "#fbbf24", fontWeight: 700, fontSize: "1.1rem", minWidth: "30px" }}>#{i + 1}</span>
                  <div>
                    <p style={{ color: "#000", fontSize: "0.9rem" }}>{item.tag}</p>
                    <p style={{ color: "rgba(0,0,0,0.3)", fontSize: "0.75rem" }}>{item.posts} posts</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

function HashIcon() {
  return (
    <div style={{ width: "32px", height: "32px", borderRadius: "8px", background: "rgba(251,191,36,0.15)", display: "flex", alignItems: "center", justifyContent: "center", color: "#fbbf24", fontWeight: 700 }}>
      #
    </div>
  );
}

import { useState, useEffect } from "react";
import {
  collection,
  query,
  onSnapshot,
  addDoc,
  doc,
  serverTimestamp,
  where,
} from "firebase/firestore";
import { MapPin, Star, Search, Filter, Heart, Calendar, Users, DollarSign, Eye, Clock } from "lucide-react";
