import { auth, db } from "../../firebase/firebase";

const venueTypes = ["All", "Banquet Hall", "Hotel", "Garden", "Rooftop", "Beach", "Church/Mosque", "Conference Center", "Restaurant", "Castle"];

const mockVenues = [
